INSERT INTO sat_questions (question_id, external_id, vault_id, disclosed_item_id, source, program, test_type, test_type_desc, domain, primary_class_cd, skill_cd, skill_desc, difficulty, score_band_range_cd, question_type, stimulus_html, stem_html, answer_options, correct_answer, answer_keys, rationale_html, correct_answer_extracted_from_rationale, image_count, parent_template_name, parent_template_id, template_cluster_id, template_cluster_name, origin, position, answer_style, section, raw_payload, created_date, updated_date) VALUES
    ($SATQ$9077be25$SATQ$, $SATQ$92844bb8-aa70-4193-b914-cb8832283584$SATQ$::uuid, $SATQ$3115fe4a-6589-43e8-a6ce-9d6cc0ae9ee7$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Information and Ideas$SATQ$, $SATQ$INI$SATQ$, $SATQ$INF$SATQ$, $SATQ$Inferences$SATQ$, $SATQ$E$SATQ$, 1, $SATQ$mcq$SATQ$, $SATQ$<p>Alice Guy-Blach&eacute; directed hundreds of films between 1896 and 1920. She wanted audiences to feel like they were watching real people on screen. She would encourage actors in her films to behave naturally. Guy-Blach&eacute; even hung a large sign reading &ldquo;Be Natural&rdquo; in the studio where she made her films. At the time, films lacked sound, so actors needed to rely solely on their bodies and facial expressions to convey emotions. As a result, actors tended to highly exaggerate their actions and expressions. The style of acting in Guy-Blach&eacute;&rsquo;s films was therefore <span aria-hidden="true">______</span><span class="sr-only">blank</span></p>$SATQ$, $SATQ$<p>Which choice most logically completes the text?</p>$SATQ$, $SATQ$[{"id":"de6020e4-09ab-4e52-95d0-c55f9bab5891","content":"<p>copied by many of Guy-Blach&eacute;&rsquo;s peers.</p>"},{"id":"24c1143f-b986-404d-bbf2-8eea5027c631","content":"<p>familiar to actors who had worked on other directors&rsquo; films.&nbsp;</p>"},{"id":"7001d3c4-a5f0-4eac-bfb5-c70611349b27","content":"<p>very unusual for the period.&nbsp;</p>"},{"id":"e84c1fff-8f28-4c14-b1bf-591d3878dde2","content":"<p>better than film acting today.</p>"}]$SATQ$::jsonb, $SATQ$["C"]$SATQ$::jsonb, $SATQ$["7001d3c4-a5f0-4eac-bfb5-c70611349b27"]$SATQ$::jsonb, $SATQ$<p>Choice C is the best answer. The text tells us that &ldquo;actors tended to highly exaggerate their actions and expressions&rdquo; in films produced from 1896 to 1920. This suggests that the natural style of acting in Guy-Blach&eacute;&rsquo;s films was very unusual for the time. </p><p>Choice A is incorrect. The text never discusses any other directors copying the style of acting found in Guy-Blach&eacute;&rsquo;s films, and in fact suggests the opposite&mdash;that it was unusual for directors to suggest this style of acting at the time. Choice B is incorrect. The text never discusses actors&rsquo; familiarity with the style of acting found in Guy-Blach&eacute;&rsquo;s films, so there isn&rsquo;t much basis for this inference. But since the text tells us that other films of the period used a highly exaggerated form of acting, we might predict that the natural style in Guy-Blach&eacute;s films would have been unfamiliar to these actors. Choice D is incorrect. The text never discusses film acting today, so there&rsquo;s no basis for this inference. </p>$SATQ$, false, 0, $SATQ$OSP-KA-INF-E005$SATQ$, $SATQ$$SATQ$, $SATQ$5b777b1a-7950-4eb2-85f0-557f212c47d4$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"9077be25","external_id":"92844bb8-aa70-4193-b914-cb8832283584","vaultid":"3115fe4a-6589-43e8-a6ce-9d6cc0ae9ee7","uId":"ca5944ca-2299-4d04-9148-fdcea009b467","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"INI","domain":"Information and Ideas","skill_cd":"INF","skill_desc":"Inferences","difficulty":"E","score_band_range_cd":1,"type":"mcq","stimulus":"<p>Alice Guy-Blach&eacute; directed hundreds of films between 1896 and 1920. She wanted audiences to feel like they were watching real people on screen. She would encourage actors in her films to behave naturally. Guy-Blach&eacute; even hung a large sign reading &ldquo;Be Natural&rdquo; in the studio where she made her films. At the time, films lacked sound, so actors needed to rely solely on their bodies and facial expressions to convey emotions. As a result, actors tended to highly exaggerate their actions and expressions. The style of acting in Guy-Blach&eacute;&rsquo;s films was therefore <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span></p>","stem":"<p>Which choice most logically completes the text?</p>","answerOptions":[{"id":"de6020e4-09ab-4e52-95d0-c55f9bab5891","content":"<p>copied by many of Guy-Blach&eacute;&rsquo;s peers.</p>"},{"id":"24c1143f-b986-404d-bbf2-8eea5027c631","content":"<p>familiar to actors who had worked on other directors&rsquo; films.&nbsp;</p>"},{"id":"7001d3c4-a5f0-4eac-bfb5-c70611349b27","content":"<p>very unusual for the period.&nbsp;</p>"},{"id":"e84c1fff-8f28-4c14-b1bf-591d3878dde2","content":"<p>better than film acting today.</p>"}],"keys":["7001d3c4-a5f0-4eac-bfb5-c70611349b27"],"correct_answer":["C"],"rationale":"<p>Choice C is the best answer. The text tells us that &ldquo;actors tended to highly exaggerate their actions and expressions&rdquo; in films produced from 1896 to 1920. This suggests that the natural style of acting in Guy-Blach&eacute;&rsquo;s films was very unusual for the time. </p><p>Choice A is incorrect. The text never discusses any other directors copying the style of acting found in Guy-Blach&eacute;&rsquo;s films, and in fact suggests the opposite&mdash;that it was unusual for directors to suggest this style of acting at the time. Choice B is incorrect. The text never discusses actors&rsquo; familiarity with the style of acting found in Guy-Blach&eacute;&rsquo;s films, so there isn&rsquo;t much basis for this inference. But since the text tells us that other films of the period used a highly exaggerated form of acting, we might predict that the natural style in Guy-Blach&eacute;s films would have been unfamiliar to these actors. Choice D is incorrect. The text never discusses film acting today, so there&rsquo;s no basis for this inference. </p>","parenttemplatename":"OSP-KA-INF-E005","parenttemplateid":"","templateclusterid":"5b777b1a-7950-4eb2-85f0-557f212c47d4","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959367,"updateDate":1691007959367}$SATQ$::jsonb, 1691007959367, 1691007959367),
    ($SATQ$923ebfe3$SATQ$, $SATQ$9398bf21-3d5c-4477-aa8b-53f600fa4ea1$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Information and Ideas$SATQ$, $SATQ$INI$SATQ$, $SATQ$CID$SATQ$, $SATQ$Central Ideas and Details$SATQ$, $SATQ$M$SATQ$, 4, $SATQ$mcq$SATQ$, $SATQ$<p>Businesses selling clothing and other fashion items face obstacles in trying to forecast how much product to order: tastes and styles change quickly, while manufacturing clothing takes a significant amount of time. Researchers Youran Fu and Marshall Fisher have found that combining sellers&rsquo; own data with information gathered from social media can dramatically improve the accuracy of such forecasts&mdash;by 24 to 57 percent in the cases they directly studied. Better predictions mean demand is easier to meet without retailers becoming overstocked.</p>$SATQ$, $SATQ$<p>Which choice best states the main idea of the text?</p>$SATQ$, $SATQ$[{"id":"4e926ddb-ab11-4225-a239-14cc967c3e37","content":"<p>Using multiple data sources can enhance the ability of sellers in the fashion industry to anticipate demand.</p>"},{"id":"9e0c8a88-a3f0-4788-901e-b6c4026cd4ba","content":"<p>Social media is revolutionizing how both sellers and researchers view the fashion industry.</p>"},{"id":"f5dd053a-e464-4533-b638-2229826f67ff","content":"<p>Becoming overstocked is the main preoccupation of sellers trying to forecast demand for fashion items.</p>"},{"id":"fa3e0d4c-053b-48a2-b1a4-42b28b6a9e84","content":"<p>Retailers can use their own data to accurately predict how tastes and styles are evolving.</p>"}]$SATQ$::jsonb, $SATQ$["A"]$SATQ$::jsonb, $SATQ$["4e926ddb-ab11-4225-a239-14cc967c3e37"]$SATQ$::jsonb, $SATQ$<p>Choice A is the best answer because it most accurately states the main idea of the text. The text explains that fashion retailers face challenges in forecasting product demand due to rapidly changing tastes and lengthy manufacturing times. It then presents research by Fu and Fisher showing that combining retailers&rsquo; own data with social media information significantly improves forecast accuracy. The text concludes by noting that better predictions help retailers meet demand without becoming overstocked. Thus, the main idea is that using multiple data sources (retailers&rsquo; own data combined with social media information) can enhance fashion retailers&rsquo; ability to anticipate demand.</p><p>Choice B is incorrect because the text doesn&rsquo;t claim that social media is revolutionizing, or fundamentally changing, how sellers and researchers view the fashion industry. The text never addresses the way the fashion industry is viewed; rather, it discusses a practical approach sellers in the industry can take to better match production with demand. Choice C is incorrect. Although avoiding overstocking is mentioned as a benefit of an approach that can help fashion sellers better predict demand, the text doesn&rsquo;t focus on overstocking or characterize it as the main concern of sellers. Rather, the text is focused on discussing the approach itself. Choice D is incorrect because the text suggests that fashion sellers encounter obstacles when using their own data to try to forecast demand as tastes and styles change; the text focuses on the idea that instead of using their own data alone, retailers should combine their own data with social media information to more accurately forecast demand.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"923ebfe3","external_id":"9398bf21-3d5c-4477-aa8b-53f600fa4ea1","vaultid":null,"uId":"f0dd8f9f-d060-4b73-a9f7-998595eec673","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"INI","domain":"Information and Ideas","skill_cd":"CID","skill_desc":"Central Ideas and Details","difficulty":"M","score_band_range_cd":4,"type":"mcq","stimulus":"<p>Businesses selling clothing and other fashion items face obstacles in trying to forecast how much product to order: tastes and styles change quickly, while manufacturing clothing takes a significant amount of time. Researchers Youran Fu and Marshall Fisher have found that combining sellers&rsquo; own data with information gathered from social media can dramatically improve the accuracy of such forecasts&mdash;by 24 to 57 percent in the cases they directly studied. Better predictions mean demand is easier to meet without retailers becoming overstocked.</p>","stem":"<p>Which choice best states the main idea of the text?</p>","answerOptions":[{"id":"4e926ddb-ab11-4225-a239-14cc967c3e37","content":"<p>Using multiple data sources can enhance the ability of sellers in the fashion industry to anticipate demand.</p>"},{"id":"9e0c8a88-a3f0-4788-901e-b6c4026cd4ba","content":"<p>Social media is revolutionizing how both sellers and researchers view the fashion industry.</p>"},{"id":"f5dd053a-e464-4533-b638-2229826f67ff","content":"<p>Becoming overstocked is the main preoccupation of sellers trying to forecast demand for fashion items.</p>"},{"id":"fa3e0d4c-053b-48a2-b1a4-42b28b6a9e84","content":"<p>Retailers can use their own data to accurately predict how tastes and styles are evolving.</p>"}],"keys":["4e926ddb-ab11-4225-a239-14cc967c3e37"],"correct_answer":["A"],"rationale":"<p>Choice A is the best answer because it most accurately states the main idea of the text. The text explains that fashion retailers face challenges in forecasting product demand due to rapidly changing tastes and lengthy manufacturing times. It then presents research by Fu and Fisher showing that combining retailers&rsquo; own data with social media information significantly improves forecast accuracy. The text concludes by noting that better predictions help retailers meet demand without becoming overstocked. Thus, the main idea is that using multiple data sources (retailers&rsquo; own data combined with social media information) can enhance fashion retailers&rsquo; ability to anticipate demand.</p><p>Choice B is incorrect because the text doesn&rsquo;t claim that social media is revolutionizing, or fundamentally changing, how sellers and researchers view the fashion industry. The text never addresses the way the fashion industry is viewed; rather, it discusses a practical approach sellers in the industry can take to better match production with demand. Choice C is incorrect. Although avoiding overstocking is mentioned as a benefit of an approach that can help fashion sellers better predict demand, the text doesn&rsquo;t focus on overstocking or characterize it as the main concern of sellers. Rather, the text is focused on discussing the approach itself. Choice D is incorrect because the text suggests that fashion sellers encounter obstacles when using their own data to try to forecast demand as tastes and styles change; the text focuses on the idea that instead of using their own data alone, retailers should combine their own data with social media information to more accurately forecast demand.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1755117061190,"updateDate":1755117061190}$SATQ$::jsonb, 1755117061190, 1755117061190),
    ($SATQ$92c2564d$SATQ$, $SATQ$e5ffa0e4-1fea-42ae-b997-44eed4a8e733$SATQ$::uuid, $SATQ$fd72433a-0513-43c5-872d-66f2b7a56a3e$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Information and Ideas$SATQ$, $SATQ$INI$SATQ$, $SATQ$CID$SATQ$, $SATQ$Central Ideas and Details$SATQ$, $SATQ$M$SATQ$, 4, $SATQ$mcq$SATQ$, $SATQ$<p>Utah is home to Pando, a colony of about 47,000 quaking aspen trees that all share a single root system. Pando is one of the largest single organisms by mass on Earth, but ecologists are worried that its growth is declining in part because of grazing by animals. The ecologists say that strong fences could prevent deer from eating young trees and help Pando start thriving again.</p>$SATQ$, $SATQ$<p>According to the text, why are ecologists worried about Pando?</p>$SATQ$, $SATQ$[{"id":"63eeec20-26cb-468a-93fe-226bea4d93d9","content":"<p>It isn&rsquo;t growing at the same rate it used to.</p>"},{"id":"0d87344b-1a32-49f5-91d7-be38af7e1252","content":"<p>It isn&rsquo;t producing young trees anymore.</p>"},{"id":"9142bdc7-87b4-4fb8-beca-8a024274d05f","content":"<p>It can&rsquo;t grow into new areas because it is blocked by fences.</p>"},{"id":"10379e4a-2806-4c04-b033-8b8c1e05b214","content":"<p>Its root system can&rsquo;t support many more new trees.</p>"}]$SATQ$::jsonb, $SATQ$["A"]$SATQ$::jsonb, $SATQ$["63eeec20-26cb-468a-93fe-226bea4d93d9"]$SATQ$::jsonb, $SATQ$<p>Choice A is the best answer because it presents an explanation that is directly stated in the text for why ecologists are worried about Pando. The text states that Pando is a colony of about 47,000 quaking aspen trees that represents one of the largest organisms on Earth. According to the text, ecologists are worried that Pando&rsquo;s growth is declining, partly because animals are feeding on the trees. In other words, the ecologists are worried that Pando isn&rsquo;t growing at the same rate it used to. </p><p>Choice B is incorrect. Rather than indicating that Pando isn&rsquo;t producing young trees anymore, the text reveals that Pando is indeed producing young trees, stating that those trees can be protected from grazing deer by strong fences. Choice C is incorrect because the text states that fences can be used to prevent deer from eating Pando&rsquo;s young trees, not that Pando itself can&rsquo;t grow in new areas because it&rsquo;s blocked by fences.&nbsp;Choice D is incorrect because the text offers no evidence that Pando&rsquo;s root system is incapable of supporting new trees or is otherwise a cause of worry for ecologists. </p>$SATQ$, false, 0, $SATQ$OSP-017-CID$SATQ$, $SATQ$$SATQ$, $SATQ$0de6e51d-fbcb-4174-bd3e-62f7a751d1c6$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"92c2564d","external_id":"e5ffa0e4-1fea-42ae-b997-44eed4a8e733","vaultid":"fd72433a-0513-43c5-872d-66f2b7a56a3e","uId":"05491934-a568-4572-b3ef-5b6678c7a3d3","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"INI","domain":"Information and Ideas","skill_cd":"CID","skill_desc":"Central Ideas and Details","difficulty":"M","score_band_range_cd":4,"type":"mcq","stimulus":"<p>Utah is home to Pando, a colony of about 47,000 quaking aspen trees that all share a single root system. Pando is one of the largest single organisms by mass on Earth, but ecologists are worried that its growth is declining in part because of grazing by animals. The ecologists say that strong fences could prevent deer from eating young trees and help Pando start thriving again.</p>","stem":"<p>According to the text, why are ecologists worried about Pando?</p>","answerOptions":[{"id":"63eeec20-26cb-468a-93fe-226bea4d93d9","content":"<p>It isn&rsquo;t growing at the same rate it used to.</p>"},{"id":"0d87344b-1a32-49f5-91d7-be38af7e1252","content":"<p>It isn&rsquo;t producing young trees anymore.</p>"},{"id":"9142bdc7-87b4-4fb8-beca-8a024274d05f","content":"<p>It can&rsquo;t grow into new areas because it is blocked by fences.</p>"},{"id":"10379e4a-2806-4c04-b033-8b8c1e05b214","content":"<p>Its root system can&rsquo;t support many more new trees.</p>"}],"keys":["63eeec20-26cb-468a-93fe-226bea4d93d9"],"correct_answer":["A"],"rationale":"<p>Choice A is the best answer because it presents an explanation that is directly stated in the text for why ecologists are worried about Pando. The text states that Pando is a colony of about 47,000 quaking aspen trees that represents one of the largest organisms on Earth. According to the text, ecologists are worried that Pando&rsquo;s growth is declining, partly because animals are feeding on the trees. In other words, the ecologists are worried that Pando isn&rsquo;t growing at the same rate it used to. </p><p>Choice B is incorrect. Rather than indicating that Pando isn&rsquo;t producing young trees anymore, the text reveals that Pando is indeed producing young trees, stating that those trees can be protected from grazing deer by strong fences. Choice C is incorrect because the text states that fences can be used to prevent deer from eating Pando&rsquo;s young trees, not that Pando itself can&rsquo;t grow in new areas because it&rsquo;s blocked by fences.&nbsp;Choice D is incorrect because the text offers no evidence that Pando&rsquo;s root system is incapable of supporting new trees or is otherwise a cause of worry for ecologists. </p>","parenttemplatename":"OSP-017-CID","parenttemplateid":"","templateclusterid":"0de6e51d-fbcb-4174-bd3e-62f7a751d1c6","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959316,"updateDate":1691007959316}$SATQ$::jsonb, 1691007959316, 1691007959316),
    ($SATQ$9391b7cc$SATQ$, $SATQ$b4910d45-076d-4ab9-9b26-f729e19c7a3b$SATQ$::uuid, $SATQ$fd883d98-eb3c-46dd-bb28-67daa354c214$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Information and Ideas$SATQ$, $SATQ$INI$SATQ$, $SATQ$INF$SATQ$, $SATQ$Inferences$SATQ$, $SATQ$H$SATQ$, 6, $SATQ$mcq$SATQ$, $SATQ$<p>If some artifacts recovered from excavations of the settlement of Kuulo Kataa, in modern Ghana, date from the thirteenth century CE, that may lend credence to claims that the settlement was founded before or around that time. There is other evidence, however, strongly supporting a fourteenth century CE founding date for Kuulo Kataa. If both the artifact dates and the fourteenth century CE founding date are correct, that would imply that <span aria-hidden="true">______</span><span class="sr-only">blank</span></p>$SATQ$, $SATQ$<p>Which choice most logically completes the text?</p>$SATQ$, $SATQ$[{"id":"27b4bfbc-4945-4d82-b7fc-d24c7f2e67af","content":"<p>artifacts from the fourteenth century CE are more commonly recovered than are artifacts from the thirteenth century CE.&nbsp;</p>"},{"id":"8fe2d56b-ba31-4baa-a0ef-42d1296f05ef","content":"<p>the artifacts originated elsewhere and eventually reached Kuulo Kataa through trade or migration.</p>"},{"id":"b0e576a7-ae5c-41c8-bc95-7f0f5ac8843e","content":"<p>Kuulo Kataa was founded by people from a different region than had previously been assumed.</p>"},{"id":"b10c4c41-2a57-4c8a-af87-851299988b5f","content":"<p>excavations at Kuulo Kataa may have inadvertently damaged some artifacts dating to the fourteenth century CE.</p>"}]$SATQ$::jsonb, $SATQ$["B"]$SATQ$::jsonb, $SATQ$["8fe2d56b-ba31-4baa-a0ef-42d1296f05ef"]$SATQ$::jsonb, $SATQ$<p>Choice B is the best answer because it most logically completes the text&rsquo;s discussion of artifacts and Kuulo Kataa&rsquo;s founding date. If it were true both that Kuulo Kataa was founded in the fourteenth century CE and that artifacts found in excavations of the settlement are from the thirteenth century CE, it would be reasonable to conclude that the artifacts weren&rsquo;t created in the Kuulo Kataa settlement. That would suggest, then, that the artifacts originated somewhere else and eventually reached the settlement through trading or as people migrated. </p><p>Choice A is incorrect because the existence of thirteenth-century CE artifacts recovered during excavations of a settlement founded in the fourteenth century CE isn&rsquo;t logically connected to artifacts from one century being more commonly recovered than artifacts from another century. Rather than suggesting anything about how frequently artifacts from different times are found, the existence of artifacts confirmed as predating the settlement&rsquo;s founding suggests that those items arrived in Kuulo Kataa during or after its establishment. Choice C is incorrect because the text focuses on time periods and says nothing about which region the founders of Kuulo Kataa have been thought to come from; similarly, the text doesn&rsquo;t suggest anything about where the thirteenth-century CE artifacts originated other than not from Kuulo Kataa. Therefore, it isn&rsquo;t logical to conclude that the mere existence of artifacts confirmed as predating the Kuulo Kataa settlement suggests that the founders of the settlement came from a particular region other than one previously assumed. Choice D is incorrect because the existence of artifacts from the thirteenth century CE at a site dated to the fourteenth century CE doesn&rsquo;t imply that fourteenth-century objects were damaged during excavations. There&rsquo;s nothing in the text to suggest that any objects were damaged; rather, the existence of artifacts confirmed as predating the settlement&rsquo;s founding suggests that those items were brought to Kuulo Kataa during or after its establishment.&nbsp;</p>$SATQ$, false, 0, $SATQ$OSP-006-INF$SATQ$, $SATQ$$SATQ$, $SATQ$eee70288-825f-4e80-87bc-afc1ac859618$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"9391b7cc","external_id":"b4910d45-076d-4ab9-9b26-f729e19c7a3b","vaultid":"fd883d98-eb3c-46dd-bb28-67daa354c214","uId":"642379fa-c753-4a6d-b0c5-284e4258cf5d","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"INI","domain":"Information and Ideas","skill_cd":"INF","skill_desc":"Inferences","difficulty":"H","score_band_range_cd":6,"type":"mcq","stimulus":"<p>If some artifacts recovered from excavations of the settlement of Kuulo Kataa, in modern Ghana, date from the thirteenth century CE, that may lend credence to claims that the settlement was founded before or around that time. There is other evidence, however, strongly supporting a fourteenth century CE founding date for Kuulo Kataa. If both the artifact dates and the fourteenth century CE founding date are correct, that would imply that <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span></p>","stem":"<p>Which choice most logically completes the text?</p>","answerOptions":[{"id":"27b4bfbc-4945-4d82-b7fc-d24c7f2e67af","content":"<p>artifacts from the fourteenth century CE are more commonly recovered than are artifacts from the thirteenth century CE.&nbsp;</p>"},{"id":"8fe2d56b-ba31-4baa-a0ef-42d1296f05ef","content":"<p>the artifacts originated elsewhere and eventually reached Kuulo Kataa through trade or migration.</p>"},{"id":"b0e576a7-ae5c-41c8-bc95-7f0f5ac8843e","content":"<p>Kuulo Kataa was founded by people from a different region than had previously been assumed.</p>"},{"id":"b10c4c41-2a57-4c8a-af87-851299988b5f","content":"<p>excavations at Kuulo Kataa may have inadvertently damaged some artifacts dating to the fourteenth century CE.</p>"}],"keys":["8fe2d56b-ba31-4baa-a0ef-42d1296f05ef"],"correct_answer":["B"],"rationale":"<p>Choice B is the best answer because it most logically completes the text&rsquo;s discussion of artifacts and Kuulo Kataa&rsquo;s founding date. If it were true both that Kuulo Kataa was founded in the fourteenth century CE and that artifacts found in excavations of the settlement are from the thirteenth century CE, it would be reasonable to conclude that the artifacts weren&rsquo;t created in the Kuulo Kataa settlement. That would suggest, then, that the artifacts originated somewhere else and eventually reached the settlement through trading or as people migrated. </p><p>Choice A is incorrect because the existence of thirteenth-century CE artifacts recovered during excavations of a settlement founded in the fourteenth century CE isn&rsquo;t logically connected to artifacts from one century being more commonly recovered than artifacts from another century. Rather than suggesting anything about how frequently artifacts from different times are found, the existence of artifacts confirmed as predating the settlement&rsquo;s founding suggests that those items arrived in Kuulo Kataa during or after its establishment. Choice C is incorrect because the text focuses on time periods and says nothing about which region the founders of Kuulo Kataa have been thought to come from; similarly, the text doesn&rsquo;t suggest anything about where the thirteenth-century CE artifacts originated other than not from Kuulo Kataa. Therefore, it isn&rsquo;t logical to conclude that the mere existence of artifacts confirmed as predating the Kuulo Kataa settlement suggests that the founders of the settlement came from a particular region other than one previously assumed. Choice D is incorrect because the existence of artifacts from the thirteenth century CE at a site dated to the fourteenth century CE doesn&rsquo;t imply that fourteenth-century objects were damaged during excavations. There&rsquo;s nothing in the text to suggest that any objects were damaged; rather, the existence of artifacts confirmed as predating the settlement&rsquo;s founding suggests that those items were brought to Kuulo Kataa during or after its establishment.&nbsp;</p>","parenttemplatename":"OSP-006-INF","parenttemplateid":"","templateclusterid":"eee70288-825f-4e80-87bc-afc1ac859618","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959312,"updateDate":1691007959312}$SATQ$::jsonb, 1691007959312, 1691007959312),
    ($SATQ$93cad661$SATQ$, $SATQ$59206731-46c7-4374-a20e-ef25e0ff20cc$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Information and Ideas$SATQ$, $SATQ$INI$SATQ$, $SATQ$INF$SATQ$, $SATQ$Inferences$SATQ$, $SATQ$E$SATQ$, 3, $SATQ$mcq$SATQ$, $SATQ$<p>A main goal of the Association for the Advancement of Creative Musicians (AACM), an arts organization founded in 1965, is to advance new works by Black musicians. The AACM achieves this goal in part by focusing on young artists. By having established musicians and composers serve as mentors, the AACM gives young artists the benefits of expert technical training and creative guidance. Numerous organizations offer similar kinds of support to new generations of painters, writers, and other artists, suggesting that <span aria-hidden="true">______</span><span class="sr-only">blank</span></p>$SATQ$, $SATQ$<p>Which choice most logically completes the text?</p>$SATQ$, $SATQ$[{"id":"74431b44-74c4-46c2-b9ef-10987860e5c6","content":"<p>artists of all ages benefit more from technical training than from creative guidance.</p>"},{"id":"a5358c26-cf0d-4b7b-b3ac-9424bee92f6b","content":"<p>many arts organizations recognize the importance of providing opportunities for young artists to learn from experienced mentors.</p>"},{"id":"05760f5d-d593-4490-837a-8515a1d2d059","content":"<p>most established artists could become even better artists by serving as mentors.</p>"},{"id":"223589f0-46cd-4a9e-96e9-ab7f408e70f8","content":"<p>finding a mentor is more important for musicians than it is for painters, writers, and other types of artists.</p>"}]$SATQ$::jsonb, $SATQ$["B"]$SATQ$::jsonb, $SATQ$["a5358c26-cf0d-4b7b-b3ac-9424bee92f6b"]$SATQ$::jsonb, $SATQ$<p>Choice B is the best answer because it presents the conclusion that most logically follows from the text&rsquo;s discussion of the relationship between the AACM&rsquo;s use of mentors to support young Black musicians and similar support that other organizations offer their young artists. According to the text, in service of AACM&rsquo;s goal to support new works by Black musicians, AACM mentors provide beneficial training and guidance to young artists. The text goes on to say that many other art organizations support new artists in similar ways, suggesting that these organizations recognize the importance of providing opportunities for young artists to learn from mentors who are established in their field.</p><p>Choice A is incorrect because the text gives no indication that technical training is more beneficial than creative guidance. The text states that AACM mentors offer both technical training and creative guidance to young artists and that other arts organizations offer similar kinds of support; however, nothing in the text suggests that young artists, or artists of any age, benefit more from technical training. Choice C is incorrect because the text is mainly concerned with the fact that established artists are mentoring young artists through AACM and other arts organizations. The text states that young musicians benefit from AACM mentors but does not address what mentors gain from the relationship, so there is no reason to conclude that most established artists could improve as artists by serving as mentors. Choice D is incorrect. Although the text indicates that mentors are beneficial to young musicians and that young people pursuing other kinds of art (including painting and writing) can also find mentors through arts organizations, the text gives no indication that mentors are more important for musicians than for other types of artists.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"93cad661","external_id":"59206731-46c7-4374-a20e-ef25e0ff20cc","vaultid":null,"uId":"fe386838-d8ea-4a33-a0d9-b0fc3c8c5ebf","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"INI","domain":"Information and Ideas","skill_cd":"INF","skill_desc":"Inferences","difficulty":"E","score_band_range_cd":3,"type":"mcq","stimulus":"<p>A main goal of the Association for the Advancement of Creative Musicians (AACM), an arts organization founded in 1965, is to advance new works by Black musicians. The AACM achieves this goal in part by focusing on young artists. By having established musicians and composers serve as mentors, the AACM gives young artists the benefits of expert technical training and creative guidance. Numerous organizations offer similar kinds of support to new generations of painters, writers, and other artists, suggesting that <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span></p>","stem":"<p>Which choice most logically completes the text?</p>","answerOptions":[{"id":"74431b44-74c4-46c2-b9ef-10987860e5c6","content":"<p>artists of all ages benefit more from technical training than from creative guidance.</p>"},{"id":"a5358c26-cf0d-4b7b-b3ac-9424bee92f6b","content":"<p>many arts organizations recognize the importance of providing opportunities for young artists to learn from experienced mentors.</p>"},{"id":"05760f5d-d593-4490-837a-8515a1d2d059","content":"<p>most established artists could become even better artists by serving as mentors.</p>"},{"id":"223589f0-46cd-4a9e-96e9-ab7f408e70f8","content":"<p>finding a mentor is more important for musicians than it is for painters, writers, and other types of artists.</p>"}],"keys":["a5358c26-cf0d-4b7b-b3ac-9424bee92f6b"],"correct_answer":["B"],"rationale":"<p>Choice B is the best answer because it presents the conclusion that most logically follows from the text&rsquo;s discussion of the relationship between the AACM&rsquo;s use of mentors to support young Black musicians and similar support that other organizations offer their young artists. According to the text, in service of AACM&rsquo;s goal to support new works by Black musicians, AACM mentors provide beneficial training and guidance to young artists. The text goes on to say that many other art organizations support new artists in similar ways, suggesting that these organizations recognize the importance of providing opportunities for young artists to learn from mentors who are established in their field.</p><p>Choice A is incorrect because the text gives no indication that technical training is more beneficial than creative guidance. The text states that AACM mentors offer both technical training and creative guidance to young artists and that other arts organizations offer similar kinds of support; however, nothing in the text suggests that young artists, or artists of any age, benefit more from technical training. Choice C is incorrect because the text is mainly concerned with the fact that established artists are mentoring young artists through AACM and other arts organizations. The text states that young musicians benefit from AACM mentors but does not address what mentors gain from the relationship, so there is no reason to conclude that most established artists could improve as artists by serving as mentors. Choice D is incorrect. Although the text indicates that mentors are beneficial to young musicians and that young people pursuing other kinds of art (including painting and writing) can also find mentors through arts organizations, the text gives no indication that mentors are more important for musicians than for other types of artists.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1730147323035,"updateDate":1730147323035}$SATQ$::jsonb, 1730147323035, 1730147323035),
    ($SATQ$9452092c$SATQ$, $SATQ$03bcea8c-439e-455a-bb85-7a05d2ed8773$SATQ$::uuid, $SATQ$e17c438b-4059-4704-92e0-c6c55efb9f78$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Information and Ideas$SATQ$, $SATQ$INI$SATQ$, $SATQ$COE$SATQ$, $SATQ$Command of Evidence$SATQ$, $SATQ$H$SATQ$, 7, $SATQ$mcq$SATQ$, $SATQ$<p><figure class="table"><table class="gdr"><caption style="caption-side: top;"><p style="text-align: center;">Effects of Mycorrhizal Fungi on 3 Plant Species</p></caption><thead><tr><th scope="col" style="text-align: center; vertical-align: bottom;">Plant species</th><th scope="col" style="text-align: center; vertical-align: bottom;">Mycorrhizal host</th><th scope="col" style="text-align: center; vertical-align: bottom;">Average mass of plants grown in soil containing mycorrhizal fungi (in grams)</th><th scope="col" style="text-align: center; vertical-align: bottom;">Average mass of plants grown in soil treated to kill fungi (in grams)</th></tr></thead><tbody><tr><th scope="row" style="text-align: left;">Corn</th><td>yes</td><td style="text-align: center;">15.1</td><td style="text-align: center;">3.8</td></tr><tr><th scope="row" style="text-align: left;">Marigold</th><td>yes</td><td style="text-align: center;">10.2</td><td style="text-align: center;">2.4</td></tr><tr><th scope="row" style="text-align: left;">Broccoli</th><td>no</td><td style="text-align: center;">7.5</td><td style="text-align: center;">7</td></tr></tbody></table></figure></p>
<p>Mycorrhizal fungi in soil benefits many plants, substantially increasing the mass of some. A student conducted an experiment to illustrate this effect. The student chose three plant species for the experiment, including two that are mycorrhizal hosts (species known to benefit from mycorrhizal fungi) and one nonmycorrhizal species (a species that doesn&rsquo;t benefit from and may even be harmed by mycorrhizal fungi). The student then grew several plants from each species both in soil containing mycorrhizal fungi and in soil that had been treated to kill mycorrhizal and other fungi. After several weeks, the student measured the plants&rsquo; average mass and was surprised to discover that <span aria-hidden="true">______</span><span class="sr-only">blank</span></p>$SATQ$, $SATQ$<p>Which choice most effectively uses data from the table to complete the statement?</p>$SATQ$, $SATQ$[{"id":"e7047fe3-ed70-43f1-8239-b2e6be822b92","content":"<p>broccoli grown in soil containing mycorrhizal fungi had a slightly higher average mass than broccoli grown in soil that had been treated to kill fungi.</p>"},{"id":"0bd807ac-453a-4d37-b110-e3a35f1f2cf6","content":"<p>corn grown in soil containing mycorrhizal fungi had a higher average mass than broccoli grown in soil containing mycorrhizal fungi.</p>"},{"id":"4cf91b39-40f3-4de9-b120-32464367d7e3","content":"<p>marigolds grown in soil containing mycorrhizal fungi had a much higher average mass than marigolds grown in soil that had been treated to kill fungi.</p>"},{"id":"ab58cd9d-5b26-4792-bf3d-b79cdbe6d608","content":"<p>corn had the highest average mass of all three species grown in soil that had been treated to kill fungi, while marigolds had the lowest.</p>"}]$SATQ$::jsonb, $SATQ$["A"]$SATQ$::jsonb, $SATQ$["e7047fe3-ed70-43f1-8239-b2e6be822b92"]$SATQ$::jsonb, $SATQ$<p>Choice A is the best answer because it most effectively uses data from the table to complete the statement. The text explains that mycorrhizal hosts are plants that benefit from the presence of mycorrhizal fungi in the soil and that some such plants produce more mass when grown in the presence of these fungi, while for nonmycorrhizal species the fungi either have no effect or may be harmful. The experiment included two mycorrhizal hosts (corn and marigold) and one nonmycorrhizal species (broccoli). Given the claim in the text that nonmycorrhizal species will see either no difference or a decrease in mass when exposed to mycorrhizal fungi, the student would likely have been surprised by the higher average mass for broccoli grown in the presence of the fungi than the broccoli grown in the soil treated to kill fungi. </p><p>Choice B is incorrect. Although this choice accurately describes the corn data from the table, the fact that the mycorrhizal host corn is more massive in the presence of the fungi likely fits with what the student expected and would therefore not be surprising.&nbsp;Choice C is incorrect. Although this choice accurately describes the marigold data from the table, the fact that the mycorrhizal host marigold is more massive in the presence of the fungi is likely what the student expected and thus would not be surprising.&nbsp;Choice D is incorrect because it does not accurately represent the data in the table&mdash;when grown in soil treated to kill fungi, corn had an average mass of 3.8 g while broccoli had an average mass of 7g&mdash;and because making comparisons among the plants in the no-fungi condition, by itself, does not provide a basis to compare the average mass of mycorrhizal hosts and nonmycorrhizal species grown in the presence of the fungi with those grown in the soil treated to kill fungi. </p>$SATQ$, false, 0, $SATQ$OSP-524-QUA$SATQ$, $SATQ$$SATQ$, $SATQ$c0224b2b-94eb-421a-9716-f5abdbf0ff75$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"9452092c","external_id":"03bcea8c-439e-455a-bb85-7a05d2ed8773","vaultid":"e17c438b-4059-4704-92e0-c6c55efb9f78","uId":"64282272-4bc3-4a30-bc1e-86df807f73a4","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"INI","domain":"Information and Ideas","skill_cd":"COE","skill_desc":"Command of Evidence","difficulty":"H","score_band_range_cd":7,"type":"mcq","stimulus":"<p><figure class=\"table\"><table class=\"gdr\"><caption style=\"caption-side: top;\"><p style=\"text-align: center;\">Effects of Mycorrhizal Fungi on 3 Plant Species</p></caption><thead><tr><th scope=\"col\" style=\"text-align: center; vertical-align: bottom;\">Plant species</th><th scope=\"col\" style=\"text-align: center; vertical-align: bottom;\">Mycorrhizal host</th><th scope=\"col\" style=\"text-align: center; vertical-align: bottom;\">Average mass of plants grown in soil containing mycorrhizal fungi (in grams)</th><th scope=\"col\" style=\"text-align: center; vertical-align: bottom;\">Average mass of plants grown in soil treated to kill fungi (in grams)</th></tr></thead><tbody><tr><th scope=\"row\" style=\"text-align: left;\">Corn</th><td>yes</td><td style=\"text-align: center;\">15.1</td><td style=\"text-align: center;\">3.8</td></tr><tr><th scope=\"row\" style=\"text-align: left;\">Marigold</th><td>yes</td><td style=\"text-align: center;\">10.2</td><td style=\"text-align: center;\">2.4</td></tr><tr><th scope=\"row\" style=\"text-align: left;\">Broccoli</th><td>no</td><td style=\"text-align: center;\">7.5</td><td style=\"text-align: center;\">7</td></tr></tbody></table></figure></p>\n<p>Mycorrhizal fungi in soil benefits many plants, substantially increasing the mass of some. A student conducted an experiment to illustrate this effect. The student chose three plant species for the experiment, including two that are mycorrhizal hosts (species known to benefit from mycorrhizal fungi) and one nonmycorrhizal species (a species that doesn&rsquo;t benefit from and may even be harmed by mycorrhizal fungi). The student then grew several plants from each species both in soil containing mycorrhizal fungi and in soil that had been treated to kill mycorrhizal and other fungi. After several weeks, the student measured the plants&rsquo; average mass and was surprised to discover that <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span></p>","stem":"<p>Which choice most effectively uses data from the table to complete the statement?</p>","answerOptions":[{"id":"e7047fe3-ed70-43f1-8239-b2e6be822b92","content":"<p>broccoli grown in soil containing mycorrhizal fungi had a slightly higher average mass than broccoli grown in soil that had been treated to kill fungi.</p>"},{"id":"0bd807ac-453a-4d37-b110-e3a35f1f2cf6","content":"<p>corn grown in soil containing mycorrhizal fungi had a higher average mass than broccoli grown in soil containing mycorrhizal fungi.</p>"},{"id":"4cf91b39-40f3-4de9-b120-32464367d7e3","content":"<p>marigolds grown in soil containing mycorrhizal fungi had a much higher average mass than marigolds grown in soil that had been treated to kill fungi.</p>"},{"id":"ab58cd9d-5b26-4792-bf3d-b79cdbe6d608","content":"<p>corn had the highest average mass of all three species grown in soil that had been treated to kill fungi, while marigolds had the lowest.</p>"}],"keys":["e7047fe3-ed70-43f1-8239-b2e6be822b92"],"correct_answer":["A"],"rationale":"<p>Choice A is the best answer because it most effectively uses data from the table to complete the statement. The text explains that mycorrhizal hosts are plants that benefit from the presence of mycorrhizal fungi in the soil and that some such plants produce more mass when grown in the presence of these fungi, while for nonmycorrhizal species the fungi either have no effect or may be harmful. The experiment included two mycorrhizal hosts (corn and marigold) and one nonmycorrhizal species (broccoli). Given the claim in the text that nonmycorrhizal species will see either no difference or a decrease in mass when exposed to mycorrhizal fungi, the student would likely have been surprised by the higher average mass for broccoli grown in the presence of the fungi than the broccoli grown in the soil treated to kill fungi. </p><p>Choice B is incorrect. Although this choice accurately describes the corn data from the table, the fact that the mycorrhizal host corn is more massive in the presence of the fungi likely fits with what the student expected and would therefore not be surprising.&nbsp;Choice C is incorrect. Although this choice accurately describes the marigold data from the table, the fact that the mycorrhizal host marigold is more massive in the presence of the fungi is likely what the student expected and thus would not be surprising.&nbsp;Choice D is incorrect because it does not accurately represent the data in the table&mdash;when grown in soil treated to kill fungi, corn had an average mass of 3.8 g while broccoli had an average mass of 7g&mdash;and because making comparisons among the plants in the no-fungi condition, by itself, does not provide a basis to compare the average mass of mycorrhizal hosts and nonmycorrhizal species grown in the presence of the fungi with those grown in the soil treated to kill fungi. </p>","parenttemplatename":"OSP-524-QUA","parenttemplateid":"","templateclusterid":"c0224b2b-94eb-421a-9716-f5abdbf0ff75","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959337,"updateDate":1691007959337}$SATQ$::jsonb, 1691007959337, 1691007959337),
    ($SATQ$94978129$SATQ$, $SATQ$9557f652-fc18-4b47-a8e1-638716b0eec7$SATQ$::uuid, $SATQ$98c6e490-b89e-419c-b1a2-e6dfcb34a85f$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Information and Ideas$SATQ$, $SATQ$INI$SATQ$, $SATQ$COE$SATQ$, $SATQ$Command of Evidence$SATQ$, $SATQ$M$SATQ$, 5, $SATQ$mcq$SATQ$, $SATQ$<p><figure class="table"><table class="gdr"><caption style="caption-side: top;"><p style="text-align: center;">Approximate Rates of Speech and Information Conveyed for Five Languages</p></caption><thead><tr><th scope="col" style="text-align: center; vertical-align: bottom;">Language</th><th scope="col" style="text-align: center; vertical-align: bottom;">Rate of speech (syllables per second)</th><th scope="col" style="text-align: center; vertical-align: bottom;">Rate of information conveyed (bits per second)</th></tr></thead><tbody><tr><th scope="row" style="text-align: left;">Serbian</th><td style="text-align: center;">7.2</td><td style="text-align: center;">39.1</td></tr><tr><th scope="row" style="text-align: left;">Spanish</th><td style="text-align: center;">7.7</td><td style="text-align: center;">42.0</td></tr><tr><th scope="row" style="text-align: left;">Vietnamese</th><td style="text-align: center;">5.3</td><td style="text-align: center;">42.5</td></tr><tr><th scope="row" style="text-align: left;">Thai</th><td style="text-align: center;">4.7</td><td style="text-align: center;">33.8</td></tr><tr><th scope="row" style="text-align: left;">Hungarian</th><td style="text-align: center;">5.9</td><td style="text-align: center;">34.6</td></tr></tbody></table></figure></p>
<p>A group of researchers working in Europe, Asia, and Oceania conducted a study to determine how quickly different Eurasian languages are typically spoken (in syllables per second) and how much information they can effectively convey (in bits per second). They found that, although languages vary widely in the speed at which they are spoken, the amount of information languages can effectively convey tends to vary much less. Thus, they claim that two languages with very different spoken rates can nonetheless convey the same amount of information in a given amount of time.&nbsp;</p>$SATQ$, $SATQ$<p>Which choice best describes data from the table that support the researchers&rsquo; claim?</p>$SATQ$, $SATQ$[{"id":"5772d6a7-49a4-43fc-9b16-d9ab2087aebe","content":"<p>Among the five languages in the table, Thai and Hungarian have the lowest rates of speech and the lowest rates of information conveyed.</p>"},{"id":"807cfc5f-06cb-4a88-a24d-905b5bed3e8c","content":"<p>Vietnamese conveys information at approximately the same rate as Spanish despite being spoken at a slower rate.</p>"},{"id":"ccd12705-b14b-4992-ba02-9a53a87ac806","content":"<p>Among the five languages in the table, the language that is spoken the fastest is also the language that conveys information the fastest.</p>"},{"id":"91d39d53-0bde-4885-9d82-9cf51bc77241","content":"<p>Serbian and Spanish are spoken at approximately the same rate, but Serbian conveys information faster than Spanish does.</p>"}]$SATQ$::jsonb, $SATQ$["B"]$SATQ$::jsonb, $SATQ$["807cfc5f-06cb-4a88-a24d-905b5bed3e8c"]$SATQ$::jsonb, $SATQ$<p>Choice B is the best answer because it provides the most direct support from the table for the claim that two languages can convey similar amounts of information even if they&rsquo;re spoken at different rates. The table shows the approximate rates at which five languages are spoken and the rates at which those five languages convey information. Vietnamese is spoken at around 5.3 syllables per second, whereas Spanish is spoken at around 7.7 syllables per second, but the two languages convey information at very similar rates: Vietnamese at a rate of around 42.5 bits per second and Spanish at a rate of around 42.0 bits per second. Thus, the description of Vietnamese conveying information at around the same rate that Spanish does despite being spoken more slowly supports the claim in the text that languages can convey the same amount of information even if spoken at different rates.&nbsp;</p><p>Choice A is incorrect because it isn&rsquo;t true that Thai and Hungarian have the lowest rates of speech of the five languages shown. According to the table, Hungarian is spoken at around 5.9 syllables per second, which is faster than Vietnamese (5.3 syllables per second). Additionally, even if this statement were true, the assertion that two languages are spoken the slowest and convey information the slowest wouldn&rsquo;t support the claim that languages can convey the same amount of information even if they&rsquo;re spoken at different rates.&nbsp;Choice C is incorrect because it isn&rsquo;t true that the fastest-spoken language (Spanish, at 7.7 syllables per second) also conveys information the fastest: Spanish conveys information at 42.0 bits per second, which is slower than the 42.5 bits-per-second rate at which Vietnamese conveys information. Additionally, even if this statement were true, the assertion that the language spoken the fastest also conveys information the fastest has no bearing on the claim that languages can convey the same amount of information even if they&rsquo;re spoken at different rates.&nbsp;Choice D is incorrect because it isn&rsquo;t true that Serbian conveys information faster than Spanish does. According to the table, Serbian conveys information at a rate of around 39.1 bits per second, which is slower than the 42.0 bits-per-second rate at which Spanish conveys information.&nbsp;</p>$SATQ$, false, 0, $SATQ$OSP-508-QUA$SATQ$, $SATQ$$SATQ$, $SATQ$d0294017-e1d8-4998-a51c-e891580b5046$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"94978129","external_id":"9557f652-fc18-4b47-a8e1-638716b0eec7","vaultid":"98c6e490-b89e-419c-b1a2-e6dfcb34a85f","uId":"d94c0985-1f46-41b0-a9e2-961c428b6680","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"INI","domain":"Information and Ideas","skill_cd":"COE","skill_desc":"Command of Evidence","difficulty":"M","score_band_range_cd":5,"type":"mcq","stimulus":"<p><figure class=\"table\"><table class=\"gdr\"><caption style=\"caption-side: top;\"><p style=\"text-align: center;\">Approximate Rates of Speech and Information Conveyed for Five Languages</p></caption><thead><tr><th scope=\"col\" style=\"text-align: center; vertical-align: bottom;\">Language</th><th scope=\"col\" style=\"text-align: center; vertical-align: bottom;\">Rate of speech (syllables per second)</th><th scope=\"col\" style=\"text-align: center; vertical-align: bottom;\">Rate of information conveyed (bits per second)</th></tr></thead><tbody><tr><th scope=\"row\" style=\"text-align: left;\">Serbian</th><td style=\"text-align: center;\">7.2</td><td style=\"text-align: center;\">39.1</td></tr><tr><th scope=\"row\" style=\"text-align: left;\">Spanish</th><td style=\"text-align: center;\">7.7</td><td style=\"text-align: center;\">42.0</td></tr><tr><th scope=\"row\" style=\"text-align: left;\">Vietnamese</th><td style=\"text-align: center;\">5.3</td><td style=\"text-align: center;\">42.5</td></tr><tr><th scope=\"row\" style=\"text-align: left;\">Thai</th><td style=\"text-align: center;\">4.7</td><td style=\"text-align: center;\">33.8</td></tr><tr><th scope=\"row\" style=\"text-align: left;\">Hungarian</th><td style=\"text-align: center;\">5.9</td><td style=\"text-align: center;\">34.6</td></tr></tbody></table></figure></p>\n<p>A group of researchers working in Europe, Asia, and Oceania conducted a study to determine how quickly different Eurasian languages are typically spoken (in syllables per second) and how much information they can effectively convey (in bits per second). They found that, although languages vary widely in the speed at which they are spoken, the amount of information languages can effectively convey tends to vary much less. Thus, they claim that two languages with very different spoken rates can nonetheless convey the same amount of information in a given amount of time.&nbsp;</p>","stem":"<p>Which choice best describes data from the table that support the researchers&rsquo; claim?</p>","answerOptions":[{"id":"5772d6a7-49a4-43fc-9b16-d9ab2087aebe","content":"<p>Among the five languages in the table, Thai and Hungarian have the lowest rates of speech and the lowest rates of information conveyed.</p>"},{"id":"807cfc5f-06cb-4a88-a24d-905b5bed3e8c","content":"<p>Vietnamese conveys information at approximately the same rate as Spanish despite being spoken at a slower rate.</p>"},{"id":"ccd12705-b14b-4992-ba02-9a53a87ac806","content":"<p>Among the five languages in the table, the language that is spoken the fastest is also the language that conveys information the fastest.</p>"},{"id":"91d39d53-0bde-4885-9d82-9cf51bc77241","content":"<p>Serbian and Spanish are spoken at approximately the same rate, but Serbian conveys information faster than Spanish does.</p>"}],"keys":["807cfc5f-06cb-4a88-a24d-905b5bed3e8c"],"correct_answer":["B"],"rationale":"<p>Choice B is the best answer because it provides the most direct support from the table for the claim that two languages can convey similar amounts of information even if they&rsquo;re spoken at different rates. The table shows the approximate rates at which five languages are spoken and the rates at which those five languages convey information. Vietnamese is spoken at around 5.3 syllables per second, whereas Spanish is spoken at around 7.7 syllables per second, but the two languages convey information at very similar rates: Vietnamese at a rate of around 42.5 bits per second and Spanish at a rate of around 42.0 bits per second. Thus, the description of Vietnamese conveying information at around the same rate that Spanish does despite being spoken more slowly supports the claim in the text that languages can convey the same amount of information even if spoken at different rates.&nbsp;</p><p>Choice A is incorrect because it isn&rsquo;t true that Thai and Hungarian have the lowest rates of speech of the five languages shown. According to the table, Hungarian is spoken at around 5.9 syllables per second, which is faster than Vietnamese (5.3 syllables per second). Additionally, even if this statement were true, the assertion that two languages are spoken the slowest and convey information the slowest wouldn&rsquo;t support the claim that languages can convey the same amount of information even if they&rsquo;re spoken at different rates.&nbsp;Choice C is incorrect because it isn&rsquo;t true that the fastest-spoken language (Spanish, at 7.7 syllables per second) also conveys information the fastest: Spanish conveys information at 42.0 bits per second, which is slower than the 42.5 bits-per-second rate at which Vietnamese conveys information. Additionally, even if this statement were true, the assertion that the language spoken the fastest also conveys information the fastest has no bearing on the claim that languages can convey the same amount of information even if they&rsquo;re spoken at different rates.&nbsp;Choice D is incorrect because it isn&rsquo;t true that Serbian conveys information faster than Spanish does. According to the table, Serbian conveys information at a rate of around 39.1 bits per second, which is slower than the 42.0 bits-per-second rate at which Spanish conveys information.&nbsp;</p>","parenttemplatename":"OSP-508-QUA","parenttemplateid":"","templateclusterid":"d0294017-e1d8-4998-a51c-e891580b5046","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959337,"updateDate":1691007959337}$SATQ$::jsonb, 1691007959337, 1691007959337),
    ($SATQ$94c54577$SATQ$, $SATQ$a834b9d5-442c-4133-b51b-b1e6ce7c584c$SATQ$::uuid, $SATQ$acae706c-4104-460b-b0b9-1aa42f967087$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Information and Ideas$SATQ$, $SATQ$INI$SATQ$, $SATQ$COE$SATQ$, $SATQ$Command of Evidence$SATQ$, $SATQ$H$SATQ$, 7, $SATQ$mcq$SATQ$, $SATQ$<p>While attending school in New York City in the 1980s, Okwui Enwezor encountered few works by African artists in exhibitions, despite New York&rsquo;s reputation as one of the best places to view contemporary art from around the world. According to an arts journalist, later in his career as a renowned curator and art historian, Enwezor sought to remedy this deficiency, not by focusing solely on modern African artists, but by showing how their work fits into the larger context of global modern art and art history. </p>$SATQ$, $SATQ$<p>Which finding, if true, would most directly support the journalist&rsquo;s claim?</p>$SATQ$, $SATQ$[{"id":"4e684add-7618-4037-b15e-066a4c356d23","content":"<p>As curator of the Haus der Kunst in Munich, Germany, Enwezor organized a retrospective of Ghanaian sculptor El Anatsui&rsquo;s work entitled <em>El Anatsui: Triumphant Scale</em>, one of the largest art exhibitions devoted to a Black artist in Europe&rsquo;s history.&nbsp;</p>"},{"id":"1d766d7a-bacd-4230-bf7e-59eda279181e","content":"<p>In the exhibition <em>Postwar: Art Between the Pacific and the Atlantic, 1945&ndash;1965</em>, Enwezor and cocurator Katy Siegel brought works by African artists such as Malangatana Ngwenya together with pieces by major figures from other countries, like US artist Andy Warhol and Mexico&rsquo;s David Siqueiros.</p>"},{"id":"7e5a164f-5a60-4ac1-8a12-c6f8ca0e9380","content":"<p>Enwezor&rsquo;s work as curator of the 2001 exhibition <em>The Short Century: Independence and Liberation Movements in Africa, 1945&ndash;1994</em> showed how African movements for independence from European colonial powers following the Second World War profoundly influenced work by African artists of the period, such as Kamala Ibrahim Ishaq and Thomas Mukarobgwa.</p>"},{"id":"9236d221-fbbc-4a5d-b8e3-211335ec271a","content":"<p>Enwezor organized the exhibition <em>In/sight: African Photographers, 1940 to the Present</em> not to emphasize a particular aesthetic trend but to demonstrate the broad range of ways in which African artists have approached the medium of photography.</p>"}]$SATQ$::jsonb, $SATQ$["B"]$SATQ$::jsonb, $SATQ$["1d766d7a-bacd-4230-bf7e-59eda279181e"]$SATQ$::jsonb, $SATQ$<p>Choice B is the best answer because it presents a finding that, if true, would most directly support the arts journalist&rsquo;s claim about Enwezor&rsquo;s work as a curator and art historian. In the text, the arts journalist asserts that Enwezor wished not just to focus on modern African artists but also to show &ldquo;how their work fits into the larger context of global modern art and art history,&rdquo; or how their work relates to artistic developments and work by other artists elsewhere in the world. The description of <em>Postwar: Art Between the Pacific and the Atlantic, 1945&ndash;1965</em> indicates that Enwezor and Siegel&rsquo;s exhibition brought works by African artists together with works by artists from other countries, thus supporting the arts journalist&rsquo;s claim that Enwezor sought to show works by African artists in a context of global modern art and art history. </p><p>Choice A is incorrect because it describes a retrospective that wouldn&rsquo;t support the arts journalist&rsquo;s claim that Enwezor wanted to show how works by modern African artists fit into the larger context of global modern art and art history. The description of <em>El Anatsui: Triumphant Scale</em> indicates that the retrospective focused only on the work of a single African artist, El Anatsui. The description doesn&rsquo;t suggest that the exhibition showed how El Anatsui&rsquo;s works fit into a global artistic context. Choice C is incorrect because it describes an exhibition that wouldn&rsquo;t support the arts journalist&rsquo;s claim that Enwezor wanted to show how works by modern African artists relate to the larger context of global modern art and art history. The description of <em>The Short Century: Independence and Liberation Movements in Africa, 1945&ndash;1994 </em>indicates that the exhibition showed how African artists were influenced by movements for independence from European colonial powers following the Second World War. Although this suggests that Enwezor intended the exhibition to place works by African artists in a political context, it doesn&rsquo;t indicate that the works were placed in a global artistic context. Choice D is incorrect because it describes an exhibition that wouldn&rsquo;t support the arts journalist&rsquo;s claim that Enwezor wanted to show how works by modern African artists relate to the larger context of global modern art and art history. The description of <em>In/sight: African Photographers, 1940 to the Present </em>indicates that the exhibition was intended to reveal the broad range of approaches taken by African photographers, not that the exhibition showed how photography by African artists fits into a global artistic context. </p>$SATQ$, false, 0, $SATQ$OSP-312-TXT$SATQ$, $SATQ$$SATQ$, $SATQ$f1992164-1340-4dda-9b05-04beb576b2a3$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"94c54577","external_id":"a834b9d5-442c-4133-b51b-b1e6ce7c584c","vaultid":"acae706c-4104-460b-b0b9-1aa42f967087","uId":"0bfd56d3-fa6c-4d4f-8d70-490438373dd3","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"INI","domain":"Information and Ideas","skill_cd":"COE","skill_desc":"Command of Evidence","difficulty":"H","score_band_range_cd":7,"type":"mcq","stimulus":"<p>While attending school in New York City in the 1980s, Okwui Enwezor encountered few works by African artists in exhibitions, despite New York&rsquo;s reputation as one of the best places to view contemporary art from around the world. According to an arts journalist, later in his career as a renowned curator and art historian, Enwezor sought to remedy this deficiency, not by focusing solely on modern African artists, but by showing how their work fits into the larger context of global modern art and art history. </p>","stem":"<p>Which finding, if true, would most directly support the journalist&rsquo;s claim?</p>","answerOptions":[{"id":"4e684add-7618-4037-b15e-066a4c356d23","content":"<p>As curator of the Haus der Kunst in Munich, Germany, Enwezor organized a retrospective of Ghanaian sculptor El Anatsui&rsquo;s work entitled <em>El Anatsui: Triumphant Scale</em>, one of the largest art exhibitions devoted to a Black artist in Europe&rsquo;s history.&nbsp;</p>"},{"id":"1d766d7a-bacd-4230-bf7e-59eda279181e","content":"<p>In the exhibition <em>Postwar: Art Between the Pacific and the Atlantic, 1945&ndash;1965</em>, Enwezor and cocurator Katy Siegel brought works by African artists such as Malangatana Ngwenya together with pieces by major figures from other countries, like US artist Andy Warhol and Mexico&rsquo;s David Siqueiros.</p>"},{"id":"7e5a164f-5a60-4ac1-8a12-c6f8ca0e9380","content":"<p>Enwezor&rsquo;s work as curator of the 2001 exhibition <em>The Short Century: Independence and Liberation Movements in Africa, 1945&ndash;1994</em> showed how African movements for independence from European colonial powers following the Second World War profoundly influenced work by African artists of the period, such as Kamala Ibrahim Ishaq and Thomas Mukarobgwa.</p>"},{"id":"9236d221-fbbc-4a5d-b8e3-211335ec271a","content":"<p>Enwezor organized the exhibition <em>In/sight: African Photographers, 1940 to the Present</em> not to emphasize a particular aesthetic trend but to demonstrate the broad range of ways in which African artists have approached the medium of photography.</p>"}],"keys":["1d766d7a-bacd-4230-bf7e-59eda279181e"],"correct_answer":["B"],"rationale":"<p>Choice B is the best answer because it presents a finding that, if true, would most directly support the arts journalist&rsquo;s claim about Enwezor&rsquo;s work as a curator and art historian. In the text, the arts journalist asserts that Enwezor wished not just to focus on modern African artists but also to show &ldquo;how their work fits into the larger context of global modern art and art history,&rdquo; or how their work relates to artistic developments and work by other artists elsewhere in the world. The description of <em>Postwar: Art Between the Pacific and the Atlantic, 1945&ndash;1965</em> indicates that Enwezor and Siegel&rsquo;s exhibition brought works by African artists together with works by artists from other countries, thus supporting the arts journalist&rsquo;s claim that Enwezor sought to show works by African artists in a context of global modern art and art history. </p><p>Choice A is incorrect because it describes a retrospective that wouldn&rsquo;t support the arts journalist&rsquo;s claim that Enwezor wanted to show how works by modern African artists fit into the larger context of global modern art and art history. The description of <em>El Anatsui: Triumphant Scale</em> indicates that the retrospective focused only on the work of a single African artist, El Anatsui. The description doesn&rsquo;t suggest that the exhibition showed how El Anatsui&rsquo;s works fit into a global artistic context. Choice C is incorrect because it describes an exhibition that wouldn&rsquo;t support the arts journalist&rsquo;s claim that Enwezor wanted to show how works by modern African artists relate to the larger context of global modern art and art history. The description of <em>The Short Century: Independence and Liberation Movements in Africa, 1945&ndash;1994 </em>indicates that the exhibition showed how African artists were influenced by movements for independence from European colonial powers following the Second World War. Although this suggests that Enwezor intended the exhibition to place works by African artists in a political context, it doesn&rsquo;t indicate that the works were placed in a global artistic context. Choice D is incorrect because it describes an exhibition that wouldn&rsquo;t support the arts journalist&rsquo;s claim that Enwezor wanted to show how works by modern African artists relate to the larger context of global modern art and art history. The description of <em>In/sight: African Photographers, 1940 to the Present </em>indicates that the exhibition was intended to reveal the broad range of approaches taken by African photographers, not that the exhibition showed how photography by African artists fits into a global artistic context. </p>","parenttemplatename":"OSP-312-TXT","parenttemplateid":"","templateclusterid":"f1992164-1340-4dda-9b05-04beb576b2a3","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959335,"updateDate":1691007959335}$SATQ$::jsonb, 1691007959335, 1691007959335),
    ($SATQ$94c726fb$SATQ$, $SATQ$7a3af365-34d0-4df4-bb8d-63cded36ae99$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Information and Ideas$SATQ$, $SATQ$INI$SATQ$, $SATQ$COE$SATQ$, $SATQ$Command of Evidence$SATQ$, $SATQ$E$SATQ$, 2, $SATQ$mcq$SATQ$, $SATQ$<p><figure class="table"><table class="gdr"><caption style="caption-side: top;"><p style="text-align: center;">Millions of Metric Tons of Copper Mined in 1995 and 2020</p></caption><thead><tr><th scope="col" style="text-align: center;vertical-align: bottom;">Country</th><th scope="col" style="text-align: center;vertical-align: bottom;">1995</th><th scope="col" style="text-align: center;vertical-align: bottom;">2020</th></tr></thead><tbody><tr><th scope="row" style="text-align: left;">Canada</th><td style="text-align: center;">0.73</td><td style="text-align: center;">0.59</td></tr><tr><th scope="row" style="text-align: left;">Indonesia</th><td style="text-align: center;">0.44</td><td style="text-align: center;">0.51</td></tr><tr><th scope="row" style="text-align: left;">Kazakhstan</th><td style="text-align: center;">0.26</td><td style="text-align: center;">0.55</td></tr><tr><th scope="row" style="text-align: left;">Chile</th><td style="text-align: center;">2.49</td><td style="text-align: center;">5.73</td></tr></tbody></table></figure></p>
<p>While doing research for a paper about copper mining, a student finds a table with information about four different countries. The student notes that the country that mined 0.55 million metric tons of copper in 2020 had mined <span aria-hidden="true">______</span><span class="sr-only">blank</span></p>$SATQ$, $SATQ$<p>Which choice most effectively uses data from the table to complete the statement?</p>$SATQ$, $SATQ$[{"id":"97fdb575-40dc-46b3-aeb1-882839f80d5d","content":"<p>0.59 million metric tons of copper in 1995.</p>"},{"id":"726349bb-ee77-4c56-b361-d3bdd3442be9","content":"<p>0.44 million metric tons of copper in 1995.</p>"},{"id":"04310ca0-d577-4d6f-b9d4-846d93a79f6b","content":"<p>0.26 million metric tons of copper in 1995.</p>"},{"id":"6e51fe59-bbbe-4f72-b945-7fb5e8d10c2f","content":"<p>2.49 million metric tons of copper in 1995.</p>"}]$SATQ$::jsonb, $SATQ$["C"]$SATQ$::jsonb, $SATQ$["04310ca0-d577-4d6f-b9d4-846d93a79f6b"]$SATQ$::jsonb, $SATQ$<p>Choice C is the best answer because it most effectively uses data from the table to complete the statement about copper mining. The table shows the amount of copper mined in each of four countries in 1995 and 2020. According to the text, a student who consults the table notes that the country that mined 0.55 million metric tons of copper in 2020 had mined a different amount in 1995. The table indicates that Kazakhstan is the country that mined 0.55 million metric tons of copper in 2020 and 0.26 million metric tons of copper in 1995.</p><p>Choice A is incorrect because it doesn&rsquo;t provide the amount of copper mined in 1995 by Kazakhstan, the country that mined 0.55 million metric tons of copper in 2020. According to the table, Canada mined 0.73 million metric tons of copper in 1995 and 0.59 million metric tons in 2020. It didn&rsquo;t mine 0.55 million metric tons in either year. Choice B is incorrect because it doesn&rsquo;t provide the amount of copper mined in 1995 by Kazakhstan, the country that mined 0.55 million metric tons of copper in 2020. According to the table, Indonesia mined 0.44 million metric tons of copper in 1995 and 0.51 million metric tons in 2020. It didn&rsquo;t mine 0.55 million metric tons in either year. Choice D is incorrect because it doesn&rsquo;t provide the amount of copper mined in 1995 by Kazakhstan, the country that mined 0.55 million metric tons of copper in 2020. According to the table, Chile mined 2.49 million metric tons of copper in 1995 and 5.73 million metric tons in 2020. It didn&rsquo;t mine 0.55 million metric tons in either year.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"94c726fb","external_id":"7a3af365-34d0-4df4-bb8d-63cded36ae99","vaultid":null,"uId":"d5ab457f-b387-4976-ae7f-0e04520aebdc","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"INI","domain":"Information and Ideas","skill_cd":"COE","skill_desc":"Command of Evidence","difficulty":"E","score_band_range_cd":2,"type":"mcq","stimulus":"<p><figure class=\"table\"><table class=\"gdr\"><caption style=\"caption-side: top;\"><p style=\"text-align: center;\">Millions of Metric Tons of Copper Mined in 1995 and 2020</p></caption><thead><tr><th scope=\"col\" style=\"text-align: center;vertical-align: bottom;\">Country</th><th scope=\"col\" style=\"text-align: center;vertical-align: bottom;\">1995</th><th scope=\"col\" style=\"text-align: center;vertical-align: bottom;\">2020</th></tr></thead><tbody><tr><th scope=\"row\" style=\"text-align: left;\">Canada</th><td style=\"text-align: center;\">0.73</td><td style=\"text-align: center;\">0.59</td></tr><tr><th scope=\"row\" style=\"text-align: left;\">Indonesia</th><td style=\"text-align: center;\">0.44</td><td style=\"text-align: center;\">0.51</td></tr><tr><th scope=\"row\" style=\"text-align: left;\">Kazakhstan</th><td style=\"text-align: center;\">0.26</td><td style=\"text-align: center;\">0.55</td></tr><tr><th scope=\"row\" style=\"text-align: left;\">Chile</th><td style=\"text-align: center;\">2.49</td><td style=\"text-align: center;\">5.73</td></tr></tbody></table></figure></p>\n<p>While doing research for a paper about copper mining, a student finds a table with information about four different countries. The student notes that the country that mined 0.55 million metric tons of copper in 2020 had mined <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span></p>","stem":"<p>Which choice most effectively uses data from the table to complete the statement?</p>","answerOptions":[{"id":"97fdb575-40dc-46b3-aeb1-882839f80d5d","content":"<p>0.59 million metric tons of copper in 1995.</p>"},{"id":"726349bb-ee77-4c56-b361-d3bdd3442be9","content":"<p>0.44 million metric tons of copper in 1995.</p>"},{"id":"04310ca0-d577-4d6f-b9d4-846d93a79f6b","content":"<p>0.26 million metric tons of copper in 1995.</p>"},{"id":"6e51fe59-bbbe-4f72-b945-7fb5e8d10c2f","content":"<p>2.49 million metric tons of copper in 1995.</p>"}],"keys":["04310ca0-d577-4d6f-b9d4-846d93a79f6b"],"correct_answer":["C"],"rationale":"<p>Choice C is the best answer because it most effectively uses data from the table to complete the statement about copper mining. The table shows the amount of copper mined in each of four countries in 1995 and 2020. According to the text, a student who consults the table notes that the country that mined 0.55 million metric tons of copper in 2020 had mined a different amount in 1995. The table indicates that Kazakhstan is the country that mined 0.55 million metric tons of copper in 2020 and 0.26 million metric tons of copper in 1995.</p><p>Choice A is incorrect because it doesn&rsquo;t provide the amount of copper mined in 1995 by Kazakhstan, the country that mined 0.55 million metric tons of copper in 2020. According to the table, Canada mined 0.73 million metric tons of copper in 1995 and 0.59 million metric tons in 2020. It didn&rsquo;t mine 0.55 million metric tons in either year. Choice B is incorrect because it doesn&rsquo;t provide the amount of copper mined in 1995 by Kazakhstan, the country that mined 0.55 million metric tons of copper in 2020. According to the table, Indonesia mined 0.44 million metric tons of copper in 1995 and 0.51 million metric tons in 2020. It didn&rsquo;t mine 0.55 million metric tons in either year. Choice D is incorrect because it doesn&rsquo;t provide the amount of copper mined in 1995 by Kazakhstan, the country that mined 0.55 million metric tons of copper in 2020. According to the table, Chile mined 2.49 million metric tons of copper in 1995 and 5.73 million metric tons in 2020. It didn&rsquo;t mine 0.55 million metric tons in either year.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1755117061178,"updateDate":1755117061178}$SATQ$::jsonb, 1755117061178, 1755117061178),
    ($SATQ$94ca8ebd$SATQ$, $SATQ$29d48243-c6fc-4b86-8b87-c1087174f7eb$SATQ$::uuid, $SATQ$de3d82dd-ed63-4853-917b-70a33fddd99a$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Information and Ideas$SATQ$, $SATQ$INI$SATQ$, $SATQ$COE$SATQ$, $SATQ$Command of Evidence$SATQ$, $SATQ$M$SATQ$, 5, $SATQ$mcq$SATQ$, $SATQ$<p>A student is examining a long, challenging poem that was initially published in a quarterly journal without explanatory notes, then later republished in a stand-alone volume containing only that poem and accompanying explanatory notes written by the poet. The student asserts that the explanatory notes were included in the republication primarily as a marketing device to help sell the stand-alone volume.</p>$SATQ$, $SATQ$<p>Which statement, if true, would most directly support the student&rsquo;s claim?</p>$SATQ$, $SATQ$[{"id":"7a85fe9b-21bf-4ea9-9181-09aa610748e8","content":"<p>The text of the poem as published in the quarterly journal is not identical to the text of the poem published in the stand-alone volume.</p>"},{"id":"a9ca8212-550b-40ea-8e2a-4ac4909f00dc","content":"<p>Many critics believe that the poet&rsquo;s explanatory notes remove certain ambiguities of the poem and make it less interesting as a result.</p>"},{"id":"5fa19c0f-b9d2-45d6-8441-5ccad6a22776","content":"<p>The publishers of the stand-alone volume requested the explanatory notes from the poet in order to make the book attractive to readers who already had a copy of the poem in a journal issue.</p>"},{"id":"dce118d4-99b5-4e68-ace4-c7942bc4e9f1","content":"<p>Correspondence between the poet and the publisher reveals that the poet&rsquo;s explanatory notes went through several drafts.</p>"}]$SATQ$::jsonb, $SATQ$["C"]$SATQ$::jsonb, $SATQ$["5fa19c0f-b9d2-45d6-8441-5ccad6a22776"]$SATQ$::jsonb, $SATQ$<p>Choice C is the best answer because it would most directly support the student&rsquo;s claim about the motivation for including explanatory notes with the stand-alone volume of the poem. The text explains that the poem had previously been published without the notes in a quarterly journal. It stands to reason that readers who had purchased the journal issue containing the poem would be unlikely to purchase an unchanged version of the poem in a stand-alone volume. However, the inclusion of notes in that volume would encourage the purchase of a stand-alone volume, since the later text would differ from the original by including the author&rsquo;s own explanation of the poem. Therefore, if it were true that the publishers of the stand-alone volume had requested the notes to make the book attractive to readers who already had a copy of the journal issue, this fact would support the student&rsquo;s claim that the notes were included primarily as a marketing device. </p><p>Choice A is incorrect because&nbsp;the student&rsquo;s claim is about the motivation for including the explanatory notes in the stand-alone volume, not about changes that might have been made to the poem itself for publication in that volume; moreover, the text never suggests that such changes were made. Choice B is incorrect because the student&rsquo;s claim is about why the explanatory notes were included in the stand-alone volume, not about how the notes affected readers&rsquo; and critics&rsquo; subsequent experience of the poem. Choice D is incorrect because the fact that the poet drafted multiple versions of the explanatory notes doesn&rsquo;t directly address the issue of whether the notes were intended as a marketing device, as the student claims; the correspondence would support this claim only if it showed that the poet had revised the notes specifically to make them useful to the marketing of the stand-alone volume. </p>$SATQ$, false, 0, $SATQ$OSP-309-TXT$SATQ$, $SATQ$$SATQ$, $SATQ$cb4c114f-868a-4be7-897b-38dd2e48bb5a$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"94ca8ebd","external_id":"29d48243-c6fc-4b86-8b87-c1087174f7eb","vaultid":"de3d82dd-ed63-4853-917b-70a33fddd99a","uId":"15375701-f425-4348-960d-cedf8fb4551e","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"INI","domain":"Information and Ideas","skill_cd":"COE","skill_desc":"Command of Evidence","difficulty":"M","score_band_range_cd":5,"type":"mcq","stimulus":"<p>A student is examining a long, challenging poem that was initially published in a quarterly journal without explanatory notes, then later republished in a stand-alone volume containing only that poem and accompanying explanatory notes written by the poet. The student asserts that the explanatory notes were included in the republication primarily as a marketing device to help sell the stand-alone volume.</p>","stem":"<p>Which statement, if true, would most directly support the student&rsquo;s claim?</p>","answerOptions":[{"id":"7a85fe9b-21bf-4ea9-9181-09aa610748e8","content":"<p>The text of the poem as published in the quarterly journal is not identical to the text of the poem published in the stand-alone volume.</p>"},{"id":"a9ca8212-550b-40ea-8e2a-4ac4909f00dc","content":"<p>Many critics believe that the poet&rsquo;s explanatory notes remove certain ambiguities of the poem and make it less interesting as a result.</p>"},{"id":"5fa19c0f-b9d2-45d6-8441-5ccad6a22776","content":"<p>The publishers of the stand-alone volume requested the explanatory notes from the poet in order to make the book attractive to readers who already had a copy of the poem in a journal issue.</p>"},{"id":"dce118d4-99b5-4e68-ace4-c7942bc4e9f1","content":"<p>Correspondence between the poet and the publisher reveals that the poet&rsquo;s explanatory notes went through several drafts.</p>"}],"keys":["5fa19c0f-b9d2-45d6-8441-5ccad6a22776"],"correct_answer":["C"],"rationale":"<p>Choice C is the best answer because it would most directly support the student&rsquo;s claim about the motivation for including explanatory notes with the stand-alone volume of the poem. The text explains that the poem had previously been published without the notes in a quarterly journal. It stands to reason that readers who had purchased the journal issue containing the poem would be unlikely to purchase an unchanged version of the poem in a stand-alone volume. However, the inclusion of notes in that volume would encourage the purchase of a stand-alone volume, since the later text would differ from the original by including the author&rsquo;s own explanation of the poem. Therefore, if it were true that the publishers of the stand-alone volume had requested the notes to make the book attractive to readers who already had a copy of the journal issue, this fact would support the student&rsquo;s claim that the notes were included primarily as a marketing device. </p><p>Choice A is incorrect because&nbsp;the student&rsquo;s claim is about the motivation for including the explanatory notes in the stand-alone volume, not about changes that might have been made to the poem itself for publication in that volume; moreover, the text never suggests that such changes were made. Choice B is incorrect because the student&rsquo;s claim is about why the explanatory notes were included in the stand-alone volume, not about how the notes affected readers&rsquo; and critics&rsquo; subsequent experience of the poem. Choice D is incorrect because the fact that the poet drafted multiple versions of the explanatory notes doesn&rsquo;t directly address the issue of whether the notes were intended as a marketing device, as the student claims; the correspondence would support this claim only if it showed that the poet had revised the notes specifically to make them useful to the marketing of the stand-alone volume. </p>","parenttemplatename":"OSP-309-TXT","parenttemplateid":"","templateclusterid":"cb4c114f-868a-4be7-897b-38dd2e48bb5a","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959335,"updateDate":1691007959335}$SATQ$::jsonb, 1691007959335, 1691007959335),
    ($SATQ$95146ebb$SATQ$, $SATQ$8966b09b-f9e6-47d0-9cfe-4335f223629d$SATQ$::uuid, $SATQ$cbc6cae4-a6ba-4813-8dc3-336bd4ab02dd$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Information and Ideas$SATQ$, $SATQ$INI$SATQ$, $SATQ$CID$SATQ$, $SATQ$Central Ideas and Details$SATQ$, $SATQ$M$SATQ$, 4, $SATQ$mcq$SATQ$, $SATQ$<p>The ice melted on a Norwegian mountain during a particularly warm summer in 2019, revealing a 1,700-year-old sandal to a mountaineer looking for artifacts. The sandal would normally have degraded quickly, but it was instead well preserved for centuries by the surrounding ice. According to archaeologist Espen Finstad and his team, the sandal, like those worn by imperial Romans, wouldn&rsquo;t have offered any protection from the cold in the mountains, so some kind of insulation, like fabric or animal skin, would have needed to be worn on the feet with the sandal.</p>$SATQ$, $SATQ$<p>What does the text indicate about the discovery of the sandal?</p>$SATQ$, $SATQ$[{"id":"32275aa8-b103-43fa-bc9a-a1c1d129142c","content":"<p>Temperatures contributed to both protecting and revealing the sandal.</p>"},{"id":"328f643c-2ec7-4deb-b2f9-ccc6476b4615","content":"<p>The discovery revealed that the Roman Empire had more influence on Norway than archaeologists previously assumed.</p>"},{"id":"b19e971b-cebd-47fc-9d1c-899088c1feda","content":"<p>Archaeologists would have found the sandal eventually without help from the general public.</p>"},{"id":"ee604188-5846-431c-9852-8c60972abb2d","content":"<p>The sandal would have degraded if it hadn&rsquo;t been removed from the ice.</p>"}]$SATQ$::jsonb, $SATQ$["A"]$SATQ$::jsonb, $SATQ$["32275aa8-b103-43fa-bc9a-a1c1d129142c"]$SATQ$::jsonb, $SATQ$<p>Choice A is the best answer. A "particularly warm summer" revealed the sandal, and centuries of ice kept it "well preserved."</p><p>Choice B is incorrect. This choice doesn&rsquo;t reflect the information in the text. The sandal is similar to Roman sandals, but there is no indication that it was a result of Roman influence. Choice C is incorrect. The text doesn&rsquo;t support this choice. We don&rsquo;t have enough information to know whether or not archaeologists would have found the sandal without people like the treasure-hunting mountaineer. Choice D is incorrect. The text says the opposite of this choice. The sandal was preserved by the ice for centuries.</p>$SATQ$, false, 0, $SATQ$OSP-KA-CID-M003$SATQ$, $SATQ$$SATQ$, $SATQ$4fdc5227-92ca-453f-a631-cb08a151360e$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"95146ebb","external_id":"8966b09b-f9e6-47d0-9cfe-4335f223629d","vaultid":"cbc6cae4-a6ba-4813-8dc3-336bd4ab02dd","uId":"c960ed2e-453f-43c8-8cef-782e246e79ca","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"INI","domain":"Information and Ideas","skill_cd":"CID","skill_desc":"Central Ideas and Details","difficulty":"M","score_band_range_cd":4,"type":"mcq","stimulus":"<p>The ice melted on a Norwegian mountain during a particularly warm summer in 2019, revealing a 1,700-year-old sandal to a mountaineer looking for artifacts. The sandal would normally have degraded quickly, but it was instead well preserved for centuries by the surrounding ice. According to archaeologist Espen Finstad and his team, the sandal, like those worn by imperial Romans, wouldn&rsquo;t have offered any protection from the cold in the mountains, so some kind of insulation, like fabric or animal skin, would have needed to be worn on the feet with the sandal.</p>","stem":"<p>What does the text indicate about the discovery of the sandal?</p>","answerOptions":[{"id":"32275aa8-b103-43fa-bc9a-a1c1d129142c","content":"<p>Temperatures contributed to both protecting and revealing the sandal.</p>"},{"id":"328f643c-2ec7-4deb-b2f9-ccc6476b4615","content":"<p>The discovery revealed that the Roman Empire had more influence on Norway than archaeologists previously assumed.</p>"},{"id":"b19e971b-cebd-47fc-9d1c-899088c1feda","content":"<p>Archaeologists would have found the sandal eventually without help from the general public.</p>"},{"id":"ee604188-5846-431c-9852-8c60972abb2d","content":"<p>The sandal would have degraded if it hadn&rsquo;t been removed from the ice.</p>"}],"keys":["32275aa8-b103-43fa-bc9a-a1c1d129142c"],"correct_answer":["A"],"rationale":"<p>Choice A is the best answer. A \"particularly warm summer\" revealed the sandal, and centuries of ice kept it \"well preserved.\"</p><p>Choice B is incorrect. This choice doesn&rsquo;t reflect the information in the text. The sandal is similar to Roman sandals, but there is no indication that it was a result of Roman influence. Choice C is incorrect. The text doesn&rsquo;t support this choice. We don&rsquo;t have enough information to know whether or not archaeologists would have found the sandal without people like the treasure-hunting mountaineer. Choice D is incorrect. The text says the opposite of this choice. The sandal was preserved by the ice for centuries.</p>","parenttemplatename":"OSP-KA-CID-M003","parenttemplateid":"","templateclusterid":"4fdc5227-92ca-453f-a631-cb08a151360e","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959360,"updateDate":1691007959360}$SATQ$::jsonb, 1691007959360, 1691007959360),
    ($SATQ$95388117$SATQ$, $SATQ$d7a2ff8d-862e-4818-9266-5024deded2c9$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Information and Ideas$SATQ$, $SATQ$INI$SATQ$, $SATQ$COE$SATQ$, $SATQ$Command of Evidence$SATQ$, $SATQ$M$SATQ$, 5, $SATQ$mcq$SATQ$, $SATQ$<p><figure class="table"><table class="gdr"><caption style="caption-side: top;"><p style="text-align: center;">Land Area Covered by Native Flowering Plants at a Site in Antarctica</p></caption><thead><tr><th scope="col" style="text-align: center;vertical-align: bottom;">Species</th><th scope="col" style="text-align: center;vertical-align: bottom;">Area covered in 2009 (in square meters)</th><th scope="col" style="text-align: center;vertical-align: bottom;">Area covered in 2018 (in square meters)</th><th scope="col" style="text-align: center;vertical-align: bottom;">Percent increase in area covered from 2009 to 2018</th></tr></thead><tbody><tr><th scope="row" style="text-align: left;"><em>Deschampsia antarctica</em></th><td style="text-align: center;">1,230</td><td style="text-align: center;">1,576</td><td style="text-align: center;">28%</td></tr><tr><th scope="row" style="text-align: left;"><em>Colobanthus quitensis</em></th><td style="text-align: center;">6.9</td><td style="text-align: center;">10.7</td><td style="text-align: center;">55%</td></tr></tbody></table></figure></p>
<p>The only flowering plant species native to Antarctica, <em>Colobanthus quitensis </em>and<em> Deschampsia antarctica</em>&nbsp;grow in places where the earth remains free of ice for much of the year. Botanist Niccoletta Cannone wondered how the warming of Antarctica&rsquo;s climate in recent years had affected these species, so she visited a site in Antarctica, first in 2009 and later in 2018, to count the number of plants growing there. Cannone found that the area of land covered by the two species had significantly expanded during the nine-year period. While both species likely benefited from warming temperatures,<em> Colobanthus quitensis </em><span aria-hidden="true">______</span><span class="sr-only">blank</span></p>$SATQ$, $SATQ$<p>Which choice most effectively uses data from the table to complete the comparison?</p>$SATQ$, $SATQ$[{"id":"3dd867d3-0dc6-407e-96fd-8b067057998d","content":"<p>suppressed the growth of <em>Deschampsia antarctica</em>, which covered a smaller area of land in 2018 than it had in 2009.</p>"},{"id":"40053968-b4e0-4c03-bb69-e70e37ca410b","content":"<p>saw a greater expansion than <em>Deschampsia antarctica </em>did, increasing the area of land it covered by more than half.</p>"},{"id":"24129ee0-0416-4ca7-80f1-3d13d156c654","content":"<p>showed a greater increase in the average size of individual plants than <em>Deschampsia antarctica </em>did.</p>"},{"id":"3678edd5-ee36-4b4b-ae52-e0de362224df","content":"<p>covered land newly freed from ice at a rate 55% faster than that of <em>Deschampsia antarctica</em>.</p>"}]$SATQ$::jsonb, $SATQ$["B"]$SATQ$::jsonb, $SATQ$["40053968-b4e0-4c03-bb69-e70e37ca410b"]$SATQ$::jsonb, $SATQ$<p>Choice B is the best answer because it most effectively uses data from the table to complete the comparison of how <em>Colobanthus quitensis</em> benefited from warming temperatures with how <em>Deschampsia antarctica</em> benefited from them. The table shows the land area covered by these two plant species at a site in Antarctica. According to the table, <em>Colobanthus quitensis</em> increased the area it covered by 55% from 2009 to 2018, whereas <em>Deschampsia antarctica</em> increased the area it covered by 28% during the same period. It therefore follows that <em>Colobanthus quitensis</em> saw a greater expansion than <em>Deschampsia antarctica</em> did and that <em>Colobanthus quitensis</em> increased the area of land it covered by more than half.</p><p>Choice A is incorrect because according to the table, <em>Deschampsia antarctica</em> covered 1,230 square meters of land in 2009 and 1,576 square meters of land in 2018. <em>Deschampsia antarctica</em> therefore covered a larger, not a smaller, area of land in 2018 than in 2009. Moreover, there&rsquo;s no information in the text or the table that suggests that one species of the plant suppressed the other. Choice C is incorrect because it inaccurately describes the data in the table. The table shows the land area covered by <em>Colobanthus quitensis</em> and <em>Deschampsia antarctica</em> and the percent increase in area covered by the two species from 2009 to 2018, not the average size of individual plants belonging to the two species. The data in the table therefore can&rsquo;t be used to make a comparison of the increase in individual plants&rsquo; average size. Choice D is incorrect because the table shows the land area covered by <em>Colobanthus quitensis</em> and <em>Deschampsia antarctica</em> and the percent increase in area covered by the two species from 2009 to 2018, not the rate at which the species increased the area they covered. Moreover, there&rsquo;s nothing in the table or the text that suggests that the areas covered by the two species were newly freed from ice.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"95388117","external_id":"d7a2ff8d-862e-4818-9266-5024deded2c9","vaultid":null,"uId":"0b597771-72eb-4744-922e-c24aa9dba250","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"INI","domain":"Information and Ideas","skill_cd":"COE","skill_desc":"Command of Evidence","difficulty":"M","score_band_range_cd":5,"type":"mcq","stimulus":"<p><figure class=\"table\"><table class=\"gdr\"><caption style=\"caption-side: top;\"><p style=\"text-align: center;\">Land Area Covered by Native Flowering Plants at a Site in Antarctica</p></caption><thead><tr><th scope=\"col\" style=\"text-align: center;vertical-align: bottom;\">Species</th><th scope=\"col\" style=\"text-align: center;vertical-align: bottom;\">Area covered in 2009 (in square meters)</th><th scope=\"col\" style=\"text-align: center;vertical-align: bottom;\">Area covered in 2018 (in square meters)</th><th scope=\"col\" style=\"text-align: center;vertical-align: bottom;\">Percent increase in area covered from 2009 to 2018</th></tr></thead><tbody><tr><th scope=\"row\" style=\"text-align: left;\"><em>Deschampsia antarctica</em></th><td style=\"text-align: center;\">1,230</td><td style=\"text-align: center;\">1,576</td><td style=\"text-align: center;\">28%</td></tr><tr><th scope=\"row\" style=\"text-align: left;\"><em>Colobanthus quitensis</em></th><td style=\"text-align: center;\">6.9</td><td style=\"text-align: center;\">10.7</td><td style=\"text-align: center;\">55%</td></tr></tbody></table></figure></p>\n<p>The only flowering plant species native to Antarctica, <em>Colobanthus quitensis </em>and<em> Deschampsia antarctica</em>&nbsp;grow in places where the earth remains free of ice for much of the year. Botanist Niccoletta Cannone wondered how the warming of Antarctica&rsquo;s climate in recent years had affected these species, so she visited a site in Antarctica, first in 2009 and later in 2018, to count the number of plants growing there. Cannone found that the area of land covered by the two species had significantly expanded during the nine-year period. While both species likely benefited from warming temperatures,<em> Colobanthus quitensis </em><span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span></p>","stem":"<p>Which choice most effectively uses data from the table to complete the comparison?</p>","answerOptions":[{"id":"3dd867d3-0dc6-407e-96fd-8b067057998d","content":"<p>suppressed the growth of <em>Deschampsia antarctica</em>, which covered a smaller area of land in 2018 than it had in 2009.</p>"},{"id":"40053968-b4e0-4c03-bb69-e70e37ca410b","content":"<p>saw a greater expansion than <em>Deschampsia antarctica </em>did, increasing the area of land it covered by more than half.</p>"},{"id":"24129ee0-0416-4ca7-80f1-3d13d156c654","content":"<p>showed a greater increase in the average size of individual plants than <em>Deschampsia antarctica </em>did.</p>"},{"id":"3678edd5-ee36-4b4b-ae52-e0de362224df","content":"<p>covered land newly freed from ice at a rate 55% faster than that of <em>Deschampsia antarctica</em>.</p>"}],"keys":["40053968-b4e0-4c03-bb69-e70e37ca410b"],"correct_answer":["B"],"rationale":"<p>Choice B is the best answer because it most effectively uses data from the table to complete the comparison of how <em>Colobanthus quitensis</em> benefited from warming temperatures with how <em>Deschampsia antarctica</em> benefited from them. The table shows the land area covered by these two plant species at a site in Antarctica. According to the table, <em>Colobanthus quitensis</em> increased the area it covered by 55% from 2009 to 2018, whereas <em>Deschampsia antarctica</em> increased the area it covered by 28% during the same period. It therefore follows that <em>Colobanthus quitensis</em> saw a greater expansion than <em>Deschampsia antarctica</em> did and that <em>Colobanthus quitensis</em> increased the area of land it covered by more than half.</p><p>Choice A is incorrect because according to the table, <em>Deschampsia antarctica</em> covered 1,230 square meters of land in 2009 and 1,576 square meters of land in 2018. <em>Deschampsia antarctica</em> therefore covered a larger, not a smaller, area of land in 2018 than in 2009. Moreover, there&rsquo;s no information in the text or the table that suggests that one species of the plant suppressed the other. Choice C is incorrect because it inaccurately describes the data in the table. The table shows the land area covered by <em>Colobanthus quitensis</em> and <em>Deschampsia antarctica</em> and the percent increase in area covered by the two species from 2009 to 2018, not the average size of individual plants belonging to the two species. The data in the table therefore can&rsquo;t be used to make a comparison of the increase in individual plants&rsquo; average size. Choice D is incorrect because the table shows the land area covered by <em>Colobanthus quitensis</em> and <em>Deschampsia antarctica</em> and the percent increase in area covered by the two species from 2009 to 2018, not the rate at which the species increased the area they covered. Moreover, there&rsquo;s nothing in the table or the text that suggests that the areas covered by the two species were newly freed from ice.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1730147323046,"updateDate":1730147323046}$SATQ$::jsonb, 1730147323046, 1730147323046),
    ($SATQ$95dbdf51$SATQ$, $SATQ$4f42766c-6041-4d86-acc8-fdb7a347eaa7$SATQ$::uuid, $SATQ$168cf551-4967-4089-bc5d-2b08947e216c$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Information and Ideas$SATQ$, $SATQ$INI$SATQ$, $SATQ$INF$SATQ$, $SATQ$Inferences$SATQ$, $SATQ$H$SATQ$, 7, $SATQ$mcq$SATQ$, $SATQ$<p>Laura Mulvey has theorized that in narrative film, shots issuing from a protagonist&rsquo;s point of view compel viewers to identify with the character. Such identification is heightened by &ldquo;invisible editing,&rdquo; or editing so inconspicuous that it renders cuts between shots almost unnoticeable. Conversely, Mulvey proposes that conspicuous editing or an absence of point-of-view shots would induce a more critical stance toward a protagonist. Consider, for example, the attic scene in Alfred Hitchcock&rsquo;s <em>The Birds</em>, a conspicuously edited sequence of tens of shots, few of which correspond to the protagonist&rsquo;s point of view. According to Mulvey&rsquo;s logic, this scene should affect viewers by <span aria-hidden="true">______</span><span class="sr-only">blank</span></p>$SATQ$, $SATQ$<p>Which choice most logically completes the text?</p>$SATQ$, $SATQ$[{"id":"a2a89fea-da5a-460a-b5a1-cdfaa377e37f","content":"<p>obscuring their awareness of the high degree of artifice involved in constructing the montage.</p>"},{"id":"b9444685-8a7f-446e-9a5e-a4fa77f5fb0b","content":"<p>lessening their identification with the protagonist, if not alienating them from the character altogether.</p>"},{"id":"c30083fe-6dd4-473b-9906-12db35ec8f76","content":"<p>compelling them to identify with the film&rsquo;s director, whose proxy is the camera, and not with the protagonist.&nbsp;</p>"},{"id":"767a6dea-ca72-4149-b48c-7f43235867c2","content":"<p>diverting their attention away from the film&rsquo;s content and toward its stylistic attributes.</p>"}]$SATQ$::jsonb, $SATQ$["B"]$SATQ$::jsonb, $SATQ$["b9444685-8a7f-446e-9a5e-a4fa77f5fb0b"]$SATQ$::jsonb, $SATQ$<p>Choice B is the best answer. We&rsquo;re told that point-of-view shots and &ldquo;invisible editing&rdquo; make audiences identify with a character. We&rsquo;re also told that obvious editing and a lack of point-of-view shots have the opposite effect. Since the sequence in <em>The Birds</em> falls into this second category, it should have the effect of reducing the audience&rsquo;s connection with the protagonist. </p><p>Choice A is incorrect. The passage doesn&rsquo;t mention viewers&rsquo; awareness of artifice (i.e., camera trickery) in films, so there&rsquo;s no basis for this inference. Choice C is incorrect. The passage doesn&rsquo;t mention the director at all, so there&rsquo;s no basis for this inference. Choice D is incorrect. The passage doesn&rsquo;t discuss whether a film&rsquo;s &ldquo;stylistic attributes&rdquo; may distract viewers from the film&rsquo;s story, so there&rsquo;s no basis for this inference. </p>$SATQ$, false, 0, $SATQ$OSP-KA-INF-H006$SATQ$, $SATQ$$SATQ$, $SATQ$b0eb8b89-9e50-4b19-8582-1eb5339a05c8$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"95dbdf51","external_id":"4f42766c-6041-4d86-acc8-fdb7a347eaa7","vaultid":"168cf551-4967-4089-bc5d-2b08947e216c","uId":"783f5491-a64e-4c6d-b0ae-64b758566782","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"INI","domain":"Information and Ideas","skill_cd":"INF","skill_desc":"Inferences","difficulty":"H","score_band_range_cd":7,"type":"mcq","stimulus":"<p>Laura Mulvey has theorized that in narrative film, shots issuing from a protagonist&rsquo;s point of view compel viewers to identify with the character. Such identification is heightened by &ldquo;invisible editing,&rdquo; or editing so inconspicuous that it renders cuts between shots almost unnoticeable. Conversely, Mulvey proposes that conspicuous editing or an absence of point-of-view shots would induce a more critical stance toward a protagonist. Consider, for example, the attic scene in Alfred Hitchcock&rsquo;s <em>The Birds</em>, a conspicuously edited sequence of tens of shots, few of which correspond to the protagonist&rsquo;s point of view. According to Mulvey&rsquo;s logic, this scene should affect viewers by <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span></p>","stem":"<p>Which choice most logically completes the text?</p>","answerOptions":[{"id":"a2a89fea-da5a-460a-b5a1-cdfaa377e37f","content":"<p>obscuring their awareness of the high degree of artifice involved in constructing the montage.</p>"},{"id":"b9444685-8a7f-446e-9a5e-a4fa77f5fb0b","content":"<p>lessening their identification with the protagonist, if not alienating them from the character altogether.</p>"},{"id":"c30083fe-6dd4-473b-9906-12db35ec8f76","content":"<p>compelling them to identify with the film&rsquo;s director, whose proxy is the camera, and not with the protagonist.&nbsp;</p>"},{"id":"767a6dea-ca72-4149-b48c-7f43235867c2","content":"<p>diverting their attention away from the film&rsquo;s content and toward its stylistic attributes.</p>"}],"keys":["b9444685-8a7f-446e-9a5e-a4fa77f5fb0b"],"correct_answer":["B"],"rationale":"<p>Choice B is the best answer. We&rsquo;re told that point-of-view shots and &ldquo;invisible editing&rdquo; make audiences identify with a character. We&rsquo;re also told that obvious editing and a lack of point-of-view shots have the opposite effect. Since the sequence in <em>The Birds</em> falls into this second category, it should have the effect of reducing the audience&rsquo;s connection with the protagonist. </p><p>Choice A is incorrect. The passage doesn&rsquo;t mention viewers&rsquo; awareness of artifice (i.e., camera trickery) in films, so there&rsquo;s no basis for this inference. Choice C is incorrect. The passage doesn&rsquo;t mention the director at all, so there&rsquo;s no basis for this inference. Choice D is incorrect. The passage doesn&rsquo;t discuss whether a film&rsquo;s &ldquo;stylistic attributes&rdquo; may distract viewers from the film&rsquo;s story, so there&rsquo;s no basis for this inference. </p>","parenttemplatename":"OSP-KA-INF-H006","parenttemplateid":"","templateclusterid":"b0eb8b89-9e50-4b19-8582-1eb5339a05c8","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959368,"updateDate":1691007959368}$SATQ$::jsonb, 1691007959368, 1691007959368),
    ($SATQ$96802cc0$SATQ$, $SATQ$c839816d-7f7e-4300-814f-1545276bc90a$SATQ$::uuid, $SATQ$158b0319-8b9b-4552-bc19-b8645fa1451c$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Information and Ideas$SATQ$, $SATQ$INI$SATQ$, $SATQ$CID$SATQ$, $SATQ$Central Ideas and Details$SATQ$, $SATQ$H$SATQ$, 7, $SATQ$mcq$SATQ$, $SATQ$<p>For centuries, the widespread acknowledgment of the involvement of the cerebellum&mdash;a dense brain structure in vertebrates&mdash;in coordinating motor control in humans has hindered recognition of other possible functions of the structure. Neuroscience research from the last two decades now suggests that the cerebellum regulates emotion and social behavior, and recent research by Ilaria Carta and colleagues has identified a pathway connecting the cerebellum to a center for motivation and reward processing known as the ventral tegmental area (VTA).</p>$SATQ$, $SATQ$<p>Which choice best states the main idea of the text?</p>$SATQ$, $SATQ$[{"id":"f2ea9647-cbac-44b3-b127-a54a7fbb012e","content":"<p>The recent verification of a pathway between the VTA and the cerebellum confirms the cerebellum&rsquo;s long-suspected role in motor coordination.</p>"},{"id":"efcf3b4e-645f-4411-8226-ea90e04009f0","content":"<p>Recent advances in the field of neuroscience have challenged widely accepted claims about the function of a pathway connecting the VTA and the cerebellum.&nbsp;</p>"},{"id":"bbc65c7c-04e4-4947-948d-555077449cff","content":"<p>The cerebellum has primarily been thought to regulate motor functioning, but in recent years neuroscience researchers have been uncovering additional functions.</p>"},{"id":"688b3892-2a08-48f6-8df9-a94325272a84","content":"<p>Technological limitations have historically hindered the study of the cerebellum, but the recent development of new technologies has led to greater insights into its functions.&nbsp;</p>"}]$SATQ$::jsonb, $SATQ$["C"]$SATQ$::jsonb, $SATQ$["bbc65c7c-04e4-4947-948d-555077449cff"]$SATQ$::jsonb, $SATQ$<p>Choice C is the best answer. The text says that the cerebellum has long been thought to regulate motor functioning, but new research shows that it may also have other functions&mdash;including regulating emotion and social behavior and some connection to motivation and rewards processing. </p><p>Choice A is incorrect. The VTA is described as &ldquo;a center for motivation and reward processing,&rdquo; and the discovery of the pathway between the VTA and the cerebellum supports the theory that the cerebellum is involved in functions other than motor coordination. Choice B is incorrect. The text says that recent research has identified this pathway, but it doesn&rsquo;t discuss any previous &ldquo;widely accepted claims&rdquo; about the pathway&rsquo;s function. The &ldquo;widespread acknowledgement&rdquo; mentioned early in the passage is about the cerebellum alone, not its connection to the VTA. Choice D is incorrect. The text never discusses any technological limitations or any new technologies. </p>$SATQ$, false, 0, $SATQ$OSP-KA-CID-H007$SATQ$, $SATQ$$SATQ$, $SATQ$d37d7494-6a0e-47ed-9aed-17b36560049f$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"96802cc0","external_id":"c839816d-7f7e-4300-814f-1545276bc90a","vaultid":"158b0319-8b9b-4552-bc19-b8645fa1451c","uId":"3fcdf345-2f9a-43b6-96aa-c50921fb5120","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"INI","domain":"Information and Ideas","skill_cd":"CID","skill_desc":"Central Ideas and Details","difficulty":"H","score_band_range_cd":7,"type":"mcq","stimulus":"<p>For centuries, the widespread acknowledgment of the involvement of the cerebellum&mdash;a dense brain structure in vertebrates&mdash;in coordinating motor control in humans has hindered recognition of other possible functions of the structure. Neuroscience research from the last two decades now suggests that the cerebellum regulates emotion and social behavior, and recent research by Ilaria Carta and colleagues has identified a pathway connecting the cerebellum to a center for motivation and reward processing known as the ventral tegmental area (VTA).</p>","stem":"<p>Which choice best states the main idea of the text?</p>","answerOptions":[{"id":"f2ea9647-cbac-44b3-b127-a54a7fbb012e","content":"<p>The recent verification of a pathway between the VTA and the cerebellum confirms the cerebellum&rsquo;s long-suspected role in motor coordination.</p>"},{"id":"efcf3b4e-645f-4411-8226-ea90e04009f0","content":"<p>Recent advances in the field of neuroscience have challenged widely accepted claims about the function of a pathway connecting the VTA and the cerebellum.&nbsp;</p>"},{"id":"bbc65c7c-04e4-4947-948d-555077449cff","content":"<p>The cerebellum has primarily been thought to regulate motor functioning, but in recent years neuroscience researchers have been uncovering additional functions.</p>"},{"id":"688b3892-2a08-48f6-8df9-a94325272a84","content":"<p>Technological limitations have historically hindered the study of the cerebellum, but the recent development of new technologies has led to greater insights into its functions.&nbsp;</p>"}],"keys":["bbc65c7c-04e4-4947-948d-555077449cff"],"correct_answer":["C"],"rationale":"<p>Choice C is the best answer. The text says that the cerebellum has long been thought to regulate motor functioning, but new research shows that it may also have other functions&mdash;including regulating emotion and social behavior and some connection to motivation and rewards processing. </p><p>Choice A is incorrect. The VTA is described as &ldquo;a center for motivation and reward processing,&rdquo; and the discovery of the pathway between the VTA and the cerebellum supports the theory that the cerebellum is involved in functions other than motor coordination. Choice B is incorrect. The text says that recent research has identified this pathway, but it doesn&rsquo;t discuss any previous &ldquo;widely accepted claims&rdquo; about the pathway&rsquo;s function. The &ldquo;widespread acknowledgement&rdquo; mentioned early in the passage is about the cerebellum alone, not its connection to the VTA. Choice D is incorrect. The text never discusses any technological limitations or any new technologies. </p>","parenttemplatename":"OSP-KA-CID-H007","parenttemplateid":"","templateclusterid":"d37d7494-6a0e-47ed-9aed-17b36560049f","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959360,"updateDate":1691007959360}$SATQ$::jsonb, 1691007959360, 1691007959360),
    ($SATQ$96d1c1fe$SATQ$, $SATQ$c5230ce5-749f-4f41-9ac4-10c8db7858c6$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Information and Ideas$SATQ$, $SATQ$INI$SATQ$, $SATQ$INF$SATQ$, $SATQ$Inferences$SATQ$, $SATQ$H$SATQ$, 7, $SATQ$mcq$SATQ$, $SATQ$<p>Tatiana R. Feuerborn and colleagues analyzed the genomes of more than a hundred domesticated dogs from sites in Siberia dating from 11,000 years ago to the present. They found that the dogs constituted a genetically isolated population of Arctic breeds until approximately 2,000 years ago, at which point there was substantial interbreeding with Near Eastern dog breeds. Furthermore, beginning around 2,000 years ago, some sites contain artifacts consistent with a Near East origin, like glass beads, but the people show no evidence of having traveled extensively outside Siberia. From this, Feuerborn and colleagues concluded that around 2,000 years ago <span aria-hidden="true">______</span><span class="sr-only">blank</span></p>$SATQ$, $SATQ$<p>Which choice most logically completes the text?</p>$SATQ$, $SATQ$[{"id":"7ba1f6ab-e5df-4f8e-81e0-36806645aed1","content":"<p>dogs and artifacts like glass beads began to be transported from the Near East to Siberia.&nbsp;</p>"},{"id":"a705b63f-33ee-4378-b1e1-1b180d38182e","content":"<p>people from Siberia began to reach the Near East, where they acquired dogs and artifacts such as glass beads.</p>"},{"id":"8367d2c4-3892-4c27-8a56-6e1711081d35","content":"<p>glass beads and other artifacts from the Near East began to be exchanged for dogs from Siberia.&nbsp;</p>"},{"id":"90bb9dac-3482-4ac7-aa55-f2b8cbbfe804","content":"<p>dogs from the Near East began to be exchanged for glass beads and other artifacts from Siberia.</p>"}]$SATQ$::jsonb, $SATQ$["A"]$SATQ$::jsonb, $SATQ$["7ba1f6ab-e5df-4f8e-81e0-36806645aed1"]$SATQ$::jsonb, $SATQ$<p>Choice A is the best answer because it presents the conclusion that most logically follows from the text&rsquo;s discussion of Feuerborn and colleagues&rsquo; findings about sites in Siberia. The text states that genomic analysis of many domesticated dogs from Siberian sites dating from the last 11,000 years revealed that the dogs represented a genetically isolated population of breeds (that is, they didn&rsquo;t reproduce with dogs of any outside breeds) until about 2,000 years ago, when there is evidence that the dogs began interbreeding with breeds from the Near East. The text also indicates that around the same time, the sites began to contain glass beads and other artifacts seeming to be from the Near East, even though there is no evidence that the people of those sites traveled widely outside Siberia. Because there is evidence of Near East dog breeds and Near East artifacts at Siberian sites beginning about 2,000 years ago but no evidence of the people&rsquo;s travel to the Near East around that time, it&rsquo;s reasonable to infer that Feuerborn and colleagues concluded that dogs and artifacts like glass beads were transported to Siberia from the Near East, starting around 2,000 years ago.</p><p>Choice B is incorrect because the text explicitly states that there is no evidence that the people of the Siberian sites 2,000 years ago traveled extensively beyond Siberia, which they would&rsquo;ve had to do to reach the Near East; therefore, it wouldn&rsquo;t make sense to conclude that the presence of Near East dog breeds and artifacts like glass beads suggests that people from Siberia began arriving in the Near East around 2,000 years ago. Choice C is incorrect because the text addresses the presence of Near East dog breeds (and evidence of interbreeding with Siberian dogs) and artifacts like glass beads at Siberian sites starting about 2,000 years ago, suggesting only that the dogs and artifacts started to arrive in Siberia around that time. The text doesn&rsquo;t suggest the purpose of the arrival of the Near East dogs and artifacts or give any indication of Siberian dog breeds being transported elsewhere through trade. Choice D is incorrect because the text addresses the presence of Near East dog breeds and artifacts like glass beads at Siberian sites starting about 2,000 years ago, suggesting only that the dogs and artifacts started to arrive in Siberia around that time; it doesn&rsquo;t suggest the purpose of this arrival and makes no mention of Siberian glass beads or other artifacts of Siberian origin.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"96d1c1fe","external_id":"c5230ce5-749f-4f41-9ac4-10c8db7858c6","vaultid":null,"uId":"a1d3342f-2161-4982-83ab-5c88a7fa31f0","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"INI","domain":"Information and Ideas","skill_cd":"INF","skill_desc":"Inferences","difficulty":"H","score_band_range_cd":7,"type":"mcq","stimulus":"<p>Tatiana R. Feuerborn and colleagues analyzed the genomes of more than a hundred domesticated dogs from sites in Siberia dating from 11,000 years ago to the present. They found that the dogs constituted a genetically isolated population of Arctic breeds until approximately 2,000 years ago, at which point there was substantial interbreeding with Near Eastern dog breeds. Furthermore, beginning around 2,000 years ago, some sites contain artifacts consistent with a Near East origin, like glass beads, but the people show no evidence of having traveled extensively outside Siberia. From this, Feuerborn and colleagues concluded that around 2,000 years ago <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span></p>","stem":"<p>Which choice most logically completes the text?</p>","answerOptions":[{"id":"7ba1f6ab-e5df-4f8e-81e0-36806645aed1","content":"<p>dogs and artifacts like glass beads began to be transported from the Near East to Siberia.&nbsp;</p>"},{"id":"a705b63f-33ee-4378-b1e1-1b180d38182e","content":"<p>people from Siberia began to reach the Near East, where they acquired dogs and artifacts such as glass beads.</p>"},{"id":"8367d2c4-3892-4c27-8a56-6e1711081d35","content":"<p>glass beads and other artifacts from the Near East began to be exchanged for dogs from Siberia.&nbsp;</p>"},{"id":"90bb9dac-3482-4ac7-aa55-f2b8cbbfe804","content":"<p>dogs from the Near East began to be exchanged for glass beads and other artifacts from Siberia.</p>"}],"keys":["7ba1f6ab-e5df-4f8e-81e0-36806645aed1"],"correct_answer":["A"],"rationale":"<p>Choice A is the best answer because it presents the conclusion that most logically follows from the text&rsquo;s discussion of Feuerborn and colleagues&rsquo; findings about sites in Siberia. The text states that genomic analysis of many domesticated dogs from Siberian sites dating from the last 11,000 years revealed that the dogs represented a genetically isolated population of breeds (that is, they didn&rsquo;t reproduce with dogs of any outside breeds) until about 2,000 years ago, when there is evidence that the dogs began interbreeding with breeds from the Near East. The text also indicates that around the same time, the sites began to contain glass beads and other artifacts seeming to be from the Near East, even though there is no evidence that the people of those sites traveled widely outside Siberia. Because there is evidence of Near East dog breeds and Near East artifacts at Siberian sites beginning about 2,000 years ago but no evidence of the people&rsquo;s travel to the Near East around that time, it&rsquo;s reasonable to infer that Feuerborn and colleagues concluded that dogs and artifacts like glass beads were transported to Siberia from the Near East, starting around 2,000 years ago.</p><p>Choice B is incorrect because the text explicitly states that there is no evidence that the people of the Siberian sites 2,000 years ago traveled extensively beyond Siberia, which they would&rsquo;ve had to do to reach the Near East; therefore, it wouldn&rsquo;t make sense to conclude that the presence of Near East dog breeds and artifacts like glass beads suggests that people from Siberia began arriving in the Near East around 2,000 years ago. Choice C is incorrect because the text addresses the presence of Near East dog breeds (and evidence of interbreeding with Siberian dogs) and artifacts like glass beads at Siberian sites starting about 2,000 years ago, suggesting only that the dogs and artifacts started to arrive in Siberia around that time. The text doesn&rsquo;t suggest the purpose of the arrival of the Near East dogs and artifacts or give any indication of Siberian dog breeds being transported elsewhere through trade. Choice D is incorrect because the text addresses the presence of Near East dog breeds and artifacts like glass beads at Siberian sites starting about 2,000 years ago, suggesting only that the dogs and artifacts started to arrive in Siberia around that time; it doesn&rsquo;t suggest the purpose of this arrival and makes no mention of Siberian glass beads or other artifacts of Siberian origin.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1730147323040,"updateDate":1730147323040}$SATQ$::jsonb, 1730147323040, 1730147323040),
    ($SATQ$9731a22b$SATQ$, $SATQ$4cdeef3b-c252-41b9-b816-e4e258e8d8e4$SATQ$::uuid, $SATQ$30a2597d-c902-4825-ba68-16481853b2a5$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Information and Ideas$SATQ$, $SATQ$INI$SATQ$, $SATQ$CID$SATQ$, $SATQ$Central Ideas and Details$SATQ$, $SATQ$H$SATQ$, 6, $SATQ$mcq$SATQ$, $SATQ$<p>Paleontologist Lucas E. Fiorelli and colleagues have reported the discovery at a mine in Brazil of several egg clutches, partially preserved single eggs, and egg shells from the Late Cretaceous period. The researchers have concluded that the area was once a nesting and breeding site for titanosaurs, a group of sauropod dinosaurs. The finding is significant given the previous lack of known nesting sites in northern regions of South America, which led many paleontologists to assume that titanosaurs migrated south to lay eggs.</p>$SATQ$, $SATQ$<p>What does the text most strongly suggest about the site discovered by the researchers?</p>$SATQ$, $SATQ$[{"id":"cf73bcde-05fe-4a61-a02a-1e96a0c72ba8","content":"<p>It is the earliest known example of a titanosaur nesting and breeding site.</p>"},{"id":"b5e12ec7-cc08-424f-b401-83c3ae97a89e","content":"<p>It was very difficult to excavate given that it was discovered in a mine.</p>"},{"id":"2c18f6ff-88d9-44a1-bae0-389ec891405e","content":"<p>It may have been occupied by other sauropods in addition to titanosaurs.</p>"},{"id":"8dd367ad-c1fa-44d6-949f-cf5fc959717f","content":"<p>It is farther north than any other nesting site discovered in South America.</p>"}]$SATQ$::jsonb, $SATQ$["D"]$SATQ$::jsonb, $SATQ$["8dd367ad-c1fa-44d6-949f-cf5fc959717f"]$SATQ$::jsonb, $SATQ$<p>Choice D is the best answer because it presents a statement about the site discovered by the researchers that is supported by the text. The text discusses Fiorelli and colleagues&rsquo; discovery of egg clutches, single eggs, and eggshells in a Brazilian mine. According to the text, the presence of these eggs, which are from the Late Cretaceous period, led the researchers to conclude that the location was once a nesting and breeding site for titanosaurs. The text then explains that the finding is important because of the &ldquo;previous lack of known nesting sites in northern regions of South America.&rdquo; If there haven&rsquo;t been any other discoveries of a nesting site in South America&rsquo;s northern regions and the site in the Brazilian mine is the first, then the text strongly suggests that the site is farther north than other nesting sites that have been discovered in South America.&nbsp;</p><p>Choice A is incorrect because the text doesn&rsquo;t suggest that the site discovered by Fiorelli and colleagues is the earliest titanosaur nesting and breeding site known to paleontologists but rather that it&rsquo;s the first nesting site found in northern regions of South America. Moreover, the text doesn&rsquo;t suggest how the timeline of the newly discovered site compares with that of other titanosaur nesting and breeding sites.&nbsp;Choice B is incorrect because there is no mention in the text about any difficulties that Fiorelli and colleagues faced when they were excavating the nesting and breeding site in the Brazilian mine.&nbsp;Choice C is incorrect because the text doesn&rsquo;t support the idea that the nesting and breeding site in the Brazilian mine was occupied by sauropods other than titanosaurs. The text simply mentions that titanosaurs are sauropod dinosaurs and presents the researchers&rsquo; conclusion that the site they discovered was for titanosaurs.&nbsp;</p>$SATQ$, false, 0, $SATQ$OSP-035-CID$SATQ$, $SATQ$$SATQ$, $SATQ$6553192c-cc70-471c-a4b8-f2d71d3c6779$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"9731a22b","external_id":"4cdeef3b-c252-41b9-b816-e4e258e8d8e4","vaultid":"30a2597d-c902-4825-ba68-16481853b2a5","uId":"30a70dcd-af9c-4271-9e9c-12b28a64cf2f","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"INI","domain":"Information and Ideas","skill_cd":"CID","skill_desc":"Central Ideas and Details","difficulty":"H","score_band_range_cd":6,"type":"mcq","stimulus":"<p>Paleontologist Lucas E. Fiorelli and colleagues have reported the discovery at a mine in Brazil of several egg clutches, partially preserved single eggs, and egg shells from the Late Cretaceous period. The researchers have concluded that the area was once a nesting and breeding site for titanosaurs, a group of sauropod dinosaurs. The finding is significant given the previous lack of known nesting sites in northern regions of South America, which led many paleontologists to assume that titanosaurs migrated south to lay eggs.</p>","stem":"<p>What does the text most strongly suggest about the site discovered by the researchers?</p>","answerOptions":[{"id":"cf73bcde-05fe-4a61-a02a-1e96a0c72ba8","content":"<p>It is the earliest known example of a titanosaur nesting and breeding site.</p>"},{"id":"b5e12ec7-cc08-424f-b401-83c3ae97a89e","content":"<p>It was very difficult to excavate given that it was discovered in a mine.</p>"},{"id":"2c18f6ff-88d9-44a1-bae0-389ec891405e","content":"<p>It may have been occupied by other sauropods in addition to titanosaurs.</p>"},{"id":"8dd367ad-c1fa-44d6-949f-cf5fc959717f","content":"<p>It is farther north than any other nesting site discovered in South America.</p>"}],"keys":["8dd367ad-c1fa-44d6-949f-cf5fc959717f"],"correct_answer":["D"],"rationale":"<p>Choice D is the best answer because it presents a statement about the site discovered by the researchers that is supported by the text. The text discusses Fiorelli and colleagues&rsquo; discovery of egg clutches, single eggs, and eggshells in a Brazilian mine. According to the text, the presence of these eggs, which are from the Late Cretaceous period, led the researchers to conclude that the location was once a nesting and breeding site for titanosaurs. The text then explains that the finding is important because of the &ldquo;previous lack of known nesting sites in northern regions of South America.&rdquo; If there haven&rsquo;t been any other discoveries of a nesting site in South America&rsquo;s northern regions and the site in the Brazilian mine is the first, then the text strongly suggests that the site is farther north than other nesting sites that have been discovered in South America.&nbsp;</p><p>Choice A is incorrect because the text doesn&rsquo;t suggest that the site discovered by Fiorelli and colleagues is the earliest titanosaur nesting and breeding site known to paleontologists but rather that it&rsquo;s the first nesting site found in northern regions of South America. Moreover, the text doesn&rsquo;t suggest how the timeline of the newly discovered site compares with that of other titanosaur nesting and breeding sites.&nbsp;Choice B is incorrect because there is no mention in the text about any difficulties that Fiorelli and colleagues faced when they were excavating the nesting and breeding site in the Brazilian mine.&nbsp;Choice C is incorrect because the text doesn&rsquo;t support the idea that the nesting and breeding site in the Brazilian mine was occupied by sauropods other than titanosaurs. The text simply mentions that titanosaurs are sauropod dinosaurs and presents the researchers&rsquo; conclusion that the site they discovered was for titanosaurs.&nbsp;</p>","parenttemplatename":"OSP-035-CID","parenttemplateid":"","templateclusterid":"6553192c-cc70-471c-a4b8-f2d71d3c6779","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959320,"updateDate":1691007959320}$SATQ$::jsonb, 1691007959320, 1691007959320),
    ($SATQ$9869c261$SATQ$, $SATQ$e9d90298-cacf-470e-a293-b7e0dd41e3d7$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Information and Ideas$SATQ$, $SATQ$INI$SATQ$, $SATQ$INF$SATQ$, $SATQ$Inferences$SATQ$, $SATQ$H$SATQ$, 7, $SATQ$mcq$SATQ$, $SATQ$<p>Data collected by the Mars rover <em>Curiosity</em> at the Gale Crater&rsquo;s Murray Formation are suggestive of hydrological deposition of sediment in the distant past. To characterize the nature of the depositional environment, Frances Rivera-Hern&aacute;ndez <span data-ssml-sub-alias="et al">et al.</span> analyzed the grain size of Murray Formation sediment, finding that although there are intervals of coarse grains, most of the sediment consists of fine grains that show signs of cracking due to episodic desiccation. Rivera-Hern&aacute;ndez <span data-ssml-sub-alias="et al">et al.</span> concluded that the coarse grains are sandstone, which tends to be deposited by flowing water, whereas the fine grains are mudstone, which is slowly deposited by settling out of suspension in low-flow water, leading the researchers to posit that <span aria-hidden="true">______</span><span class="sr-only">blank</span></p>$SATQ$, $SATQ$<p>Which choice most logically completes the text?</p>$SATQ$, $SATQ$[{"id":"5e924d1e-4644-45f6-a272-3ee53961d965","content":"<p>although the area of the Murray Formation experienced a prolonged period of dryness that prevented a lake from forming, water flowing from a distant source was present.&nbsp;</p>"},{"id":"26073cb3-a015-42d2-bdae-675c9426e121","content":"<p>a lake existed at the Murray Formation for a prolonged period, though the lake occasionally experienced drying and there were periods in which one or more streams were present.&nbsp;</p>"},{"id":"b3c141b3-e829-4fbb-a393-055aacc10631","content":"<p>one or more streams existed at the Murray Formation for an extended period until being replaced by a lake that persisted for only a brief period before permanently drying.</p>"},{"id":"22351aa6-aad0-4cdf-848e-885a55f3ad68","content":"<p>a stream-fed lake was present at the Murray Formation for an extended period, and although the streams experienced occasional drying, the lake did not.&nbsp;</p>"}]$SATQ$::jsonb, $SATQ$["B"]$SATQ$::jsonb, $SATQ$["26073cb3-a015-42d2-bdae-675c9426e121"]$SATQ$::jsonb, $SATQ$<p>Choice B is the best answer because it most logically completes the text&rsquo;s discussion of the sediments found at the Gale Crater&rsquo;s Murray Formation on Mars. The text states that data gathered by the <em>Curiosity</em> rover suggest that bodies of water deposited sediment on Mars&rsquo;s surface long ago. The text goes on to say that studying the sediment, Rivera-Hern&aacute;ndez et al. found some coarse grains they believe are sandstone, which tends to be left by flowing water, and many more fine grains they believe are mudstone, which tends to slowly sink in low-flow water. The text further indicates that the researchers noted cracks in the fine grains that suggest there were cycles of desiccation, or drying, at the site. Taken together, this information suggests that a lake (a body of low-flow water) existed at the site for a prolonged period but occasionally experienced drying and that there were periods in which one or more streams (flowing water) were present, since the extended existence of a lake would account for the abundance of fine grains, periods of drying would account for the cracks in the fine grains, and periods with streams would account for the sections of coarse grains.</p><p>Choice A is incorrect because the text indicates that an abundance of fine grains of sediment was found at the Murray Formation site, which suggests that a low-flow water source (such as a lake) <em>was</em> present. Further, the text makes no mention of where the water at the site may have originated from. Choice C is incorrect because the evidence described in the text doesn&rsquo;t support the idea that there were streams at the Murray Formation for an extended period and a lake for just a short time. The abundance of fine grains suggests that a lake (a body of low-flow water) was present for an extended time, not just a short time, and the sections of coarse grains suggest that one or more streams (bodies of flowing water) were intermittently present while the lake existed, not at a separate time. Choice D is incorrect. Although the text suggests that both a low-flow body of water (such as a lake) and flowing water (such as streams) existed at the Murray Formation site, meaning that there could have been a stream-fed lake, the text explains that the fine grains that signify the presence of a lake exhibit cracking that indicates periods of desiccation, or drying, which suggests that a lake was present but <em>did</em> occasionally dry out.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"9869c261","external_id":"e9d90298-cacf-470e-a293-b7e0dd41e3d7","vaultid":null,"uId":"fc843bf1-6099-4ab9-a73f-0527da60111a","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"INI","domain":"Information and Ideas","skill_cd":"INF","skill_desc":"Inferences","difficulty":"H","score_band_range_cd":7,"type":"mcq","stimulus":"<p>Data collected by the Mars rover <em>Curiosity</em> at the Gale Crater&rsquo;s Murray Formation are suggestive of hydrological deposition of sediment in the distant past. To characterize the nature of the depositional environment, Frances Rivera-Hern&aacute;ndez <span data-ssml-sub-alias=\"et al\">et al.</span> analyzed the grain size of Murray Formation sediment, finding that although there are intervals of coarse grains, most of the sediment consists of fine grains that show signs of cracking due to episodic desiccation. Rivera-Hern&aacute;ndez <span data-ssml-sub-alias=\"et al\">et al.</span> concluded that the coarse grains are sandstone, which tends to be deposited by flowing water, whereas the fine grains are mudstone, which is slowly deposited by settling out of suspension in low-flow water, leading the researchers to posit that <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span></p>","stem":"<p>Which choice most logically completes the text?</p>","answerOptions":[{"id":"5e924d1e-4644-45f6-a272-3ee53961d965","content":"<p>although the area of the Murray Formation experienced a prolonged period of dryness that prevented a lake from forming, water flowing from a distant source was present.&nbsp;</p>"},{"id":"26073cb3-a015-42d2-bdae-675c9426e121","content":"<p>a lake existed at the Murray Formation for a prolonged period, though the lake occasionally experienced drying and there were periods in which one or more streams were present.&nbsp;</p>"},{"id":"b3c141b3-e829-4fbb-a393-055aacc10631","content":"<p>one or more streams existed at the Murray Formation for an extended period until being replaced by a lake that persisted for only a brief period before permanently drying.</p>"},{"id":"22351aa6-aad0-4cdf-848e-885a55f3ad68","content":"<p>a stream-fed lake was present at the Murray Formation for an extended period, and although the streams experienced occasional drying, the lake did not.&nbsp;</p>"}],"keys":["26073cb3-a015-42d2-bdae-675c9426e121"],"correct_answer":["B"],"rationale":"<p>Choice B is the best answer because it most logically completes the text&rsquo;s discussion of the sediments found at the Gale Crater&rsquo;s Murray Formation on Mars. The text states that data gathered by the <em>Curiosity</em> rover suggest that bodies of water deposited sediment on Mars&rsquo;s surface long ago. The text goes on to say that studying the sediment, Rivera-Hern&aacute;ndez et al. found some coarse grains they believe are sandstone, which tends to be left by flowing water, and many more fine grains they believe are mudstone, which tends to slowly sink in low-flow water. The text further indicates that the researchers noted cracks in the fine grains that suggest there were cycles of desiccation, or drying, at the site. Taken together, this information suggests that a lake (a body of low-flow water) existed at the site for a prolonged period but occasionally experienced drying and that there were periods in which one or more streams (flowing water) were present, since the extended existence of a lake would account for the abundance of fine grains, periods of drying would account for the cracks in the fine grains, and periods with streams would account for the sections of coarse grains.</p><p>Choice A is incorrect because the text indicates that an abundance of fine grains of sediment was found at the Murray Formation site, which suggests that a low-flow water source (such as a lake) <em>was</em> present. Further, the text makes no mention of where the water at the site may have originated from. Choice C is incorrect because the evidence described in the text doesn&rsquo;t support the idea that there were streams at the Murray Formation for an extended period and a lake for just a short time. The abundance of fine grains suggests that a lake (a body of low-flow water) was present for an extended time, not just a short time, and the sections of coarse grains suggest that one or more streams (bodies of flowing water) were intermittently present while the lake existed, not at a separate time. Choice D is incorrect. Although the text suggests that both a low-flow body of water (such as a lake) and flowing water (such as streams) existed at the Murray Formation site, meaning that there could have been a stream-fed lake, the text explains that the fine grains that signify the presence of a lake exhibit cracking that indicates periods of desiccation, or drying, which suggests that a lake was present but <em>did</em> occasionally dry out.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1743430669214,"updateDate":1743430669214}$SATQ$::jsonb, 1743430669214, 1743430669214),
    ($SATQ$98d0a5d7$SATQ$, $SATQ$76c41880-b3cd-4f49-86f6-2e9fb2b14aa9$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Information and Ideas$SATQ$, $SATQ$INI$SATQ$, $SATQ$COE$SATQ$, $SATQ$Command of Evidence$SATQ$, $SATQ$H$SATQ$, 7, $SATQ$mcq$SATQ$, $SATQ$<p>Almost all works of fiction contain references to the progression of time, including the time of day when events in a story take place. In a 2020 study, Allen Kim, Charuta Pethe, and Steven Skiena claim that an observable pattern in such references reflects a shift in human behavior prompted by the spread of electric lighting in the late nineteenth century. The researchers drew this conclusion from an analysis of more than 50,000 novels spanning many centuries and cultures, using software to recognize and tally both specific time references&mdash;that is, clock phrases, such as 7 <span data-ssml-sub-alias="a m">a.m.</span> or 2:30 <span data-ssml-sub-alias="p m">p.m.</span>&mdash;and implied ones, such as mentions of meals typically associated with a particular time of day.</p>$SATQ$, $SATQ$<p>Which finding from the study, if true, would most directly support the researchers&rsquo; conclusion?</p>$SATQ$, $SATQ$[{"id":"f638bcf7-d650-4c7d-9887-ef75445f6052","content":"<p>Novels published after the year 1800 include the clock phrase 10 <span data-ssml-sub-alias=\"a m\">a.m.</span> less often than novels published before the year 1800 do.</p>"},{"id":"097b9496-6862-47bc-b714-3279cc7c58a8","content":"<p>Novels published after <span data-ssml-say-as=\"date\">1880</span> contain significantly more references to activities occurring after 10 <span data-ssml-sub-alias=\"p m\">p.m.</span> than do novels from earlier periods.</p>"},{"id":"a7045e9f-e281-439f-a84d-7b24679d8cd0","content":"<p>Among novels published in the nineteenth century, implied time references become steadily more common than clock phrases as publication dates approach 1900.</p>"},{"id":"a79baa50-b421-4069-a35a-f28971e9366e","content":"<p>The time references of noon (12 <span data-ssml-sub-alias=\"p m\">p.m.</span>) and midnight (12 <span data-ssml-sub-alias=\"a m\">a.m.</span>) are used with roughly the same frequency in the novels.</p>"}]$SATQ$::jsonb, $SATQ$["B"]$SATQ$::jsonb, $SATQ$["097b9496-6862-47bc-b714-3279cc7c58a8"]$SATQ$::jsonb, $SATQ$<p>Choice B is the best answer because it presents a finding that, if true, would most directly support the researchers&rsquo; conclusion that an observable pattern in time references in novels reflects a shift in human behavior prompted by the spread of electric lighting in the late nineteenth century. If novels published after 1880 contain significantly more references to activities occurring after 10 p.m. than novels from earlier periods do, this would suggest a change in human behavior and daily routines enabled by the availability of electric lighting. Before electric lighting&mdash;which provided illumination more easily than other available forms of light&mdash;many activities ceased after nightfall, so references to late-night activities would be less common in earlier novels. An increase in such references after 1880 would align with the researchers&rsquo; conclusion, reflecting an increase in late-night activities made possible by electric lighting.</p><p>Choice A is incorrect because a decrease in references to 10 a.m. after the year 1800 would not support the researchers&rsquo; conclusion involving a shift in human behavior prompted by the spread of electric lighting toward the end of the 1800s. The time of 10 a.m. is in the morning and, in most places, characterized by daylight, so a change in references to that time would not be clearly linked to the impact of electric lighting. Choice C is incorrect because while an increase in implied time references relative to clock phrases in nineteenth-century novels could suggest a change in writing style or conventions, it does not directly support the conclusion involving a shift in human behavior prompted by the spread of electric lighting. The text indicates that the researchers&rsquo; conclusion is based on the content of the time references themselves, not the phrasing used. Choice D is incorrect. If references to noon and midnight are used with roughly the same frequency in all the novels analyzed by the researchers, this would reflect a lack of change in human behavior with regard to time and therefore would not support the researchers&rsquo; conclusion involving a shift in human behavior that occurred in response to the spread of electric lighting.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"98d0a5d7","external_id":"76c41880-b3cd-4f49-86f6-2e9fb2b14aa9","vaultid":null,"uId":"0aef6fb9-a639-4c27-a282-47a862552809","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"INI","domain":"Information and Ideas","skill_cd":"COE","skill_desc":"Command of Evidence","difficulty":"H","score_band_range_cd":7,"type":"mcq","stimulus":"<p>Almost all works of fiction contain references to the progression of time, including the time of day when events in a story take place. In a 2020 study, Allen Kim, Charuta Pethe, and Steven Skiena claim that an observable pattern in such references reflects a shift in human behavior prompted by the spread of electric lighting in the late nineteenth century. The researchers drew this conclusion from an analysis of more than 50,000 novels spanning many centuries and cultures, using software to recognize and tally both specific time references&mdash;that is, clock phrases, such as 7 <span data-ssml-sub-alias=\"a m\">a.m.</span> or 2:30 <span data-ssml-sub-alias=\"p m\">p.m.</span>&mdash;and implied ones, such as mentions of meals typically associated with a particular time of day.</p>","stem":"<p>Which finding from the study, if true, would most directly support the researchers&rsquo; conclusion?</p>","answerOptions":[{"id":"f638bcf7-d650-4c7d-9887-ef75445f6052","content":"<p>Novels published after the year 1800 include the clock phrase 10 <span data-ssml-sub-alias=\"a m\">a.m.</span> less often than novels published before the year 1800 do.</p>"},{"id":"097b9496-6862-47bc-b714-3279cc7c58a8","content":"<p>Novels published after <span data-ssml-say-as=\"date\">1880</span> contain significantly more references to activities occurring after 10 <span data-ssml-sub-alias=\"p m\">p.m.</span> than do novels from earlier periods.</p>"},{"id":"a7045e9f-e281-439f-a84d-7b24679d8cd0","content":"<p>Among novels published in the nineteenth century, implied time references become steadily more common than clock phrases as publication dates approach 1900.</p>"},{"id":"a79baa50-b421-4069-a35a-f28971e9366e","content":"<p>The time references of noon (12 <span data-ssml-sub-alias=\"p m\">p.m.</span>) and midnight (12 <span data-ssml-sub-alias=\"a m\">a.m.</span>) are used with roughly the same frequency in the novels.</p>"}],"keys":["097b9496-6862-47bc-b714-3279cc7c58a8"],"correct_answer":["B"],"rationale":"<p>Choice B is the best answer because it presents a finding that, if true, would most directly support the researchers&rsquo; conclusion that an observable pattern in time references in novels reflects a shift in human behavior prompted by the spread of electric lighting in the late nineteenth century. If novels published after 1880 contain significantly more references to activities occurring after 10 p.m. than novels from earlier periods do, this would suggest a change in human behavior and daily routines enabled by the availability of electric lighting. Before electric lighting&mdash;which provided illumination more easily than other available forms of light&mdash;many activities ceased after nightfall, so references to late-night activities would be less common in earlier novels. An increase in such references after 1880 would align with the researchers&rsquo; conclusion, reflecting an increase in late-night activities made possible by electric lighting.</p><p>Choice A is incorrect because a decrease in references to 10 a.m. after the year 1800 would not support the researchers&rsquo; conclusion involving a shift in human behavior prompted by the spread of electric lighting toward the end of the 1800s. The time of 10 a.m. is in the morning and, in most places, characterized by daylight, so a change in references to that time would not be clearly linked to the impact of electric lighting. Choice C is incorrect because while an increase in implied time references relative to clock phrases in nineteenth-century novels could suggest a change in writing style or conventions, it does not directly support the conclusion involving a shift in human behavior prompted by the spread of electric lighting. The text indicates that the researchers&rsquo; conclusion is based on the content of the time references themselves, not the phrasing used. Choice D is incorrect. If references to noon and midnight are used with roughly the same frequency in all the novels analyzed by the researchers, this would reflect a lack of change in human behavior with regard to time and therefore would not support the researchers&rsquo; conclusion involving a shift in human behavior that occurred in response to the spread of electric lighting.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1743430669208,"updateDate":1743430669208}$SATQ$::jsonb, 1743430669208, 1743430669208),
    ($SATQ$98fd50f2$SATQ$, $SATQ$4de54913-205f-481c-b12b-f64e8d8f81d7$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Information and Ideas$SATQ$, $SATQ$INI$SATQ$, $SATQ$COE$SATQ$, $SATQ$Command of Evidence$SATQ$, $SATQ$M$SATQ$, 4, $SATQ$mcq$SATQ$, $SATQ$<p>Among the most visited art museums in the world, the Galleria dell&rsquo;Accademia in Florence had approximately 1.7 million visitors in 2019. The Galleria dell&rsquo;Accademia also offers virtual tours that art lovers can view online for free. Although there were initial concerns that people who viewed the virtual tours would then consider an in-person visit unnecessary, museum administrators claim that their surveys of in-person visitors show that those concerns were unjustified.</p>$SATQ$, $SATQ$<p>Which statement, if true, would most directly support the administrators&rsquo; claim?</p>$SATQ$, $SATQ$[{"id":"2f741f4c-c41b-43c5-ad74-c659f55fa0ad","content":"<p>Many surveyed visitors to the Galleria dell&rsquo;Accademia indicated that the virtual tours convinced them to plan an in-person visit.&nbsp;</p>"},{"id":"61a3f730-12d2-4a32-9d9b-d939e425d5fa","content":"<p>Most surveyed visitors to the Galleria dell&rsquo;Accademia indicated that they were unaware of the virtual tours before their first in-person visit.</p>"},{"id":"e133b8e7-98f4-42ab-9e74-4d2c5bddfeae","content":"<p>Most surveyed visitors to the Galleria dell&rsquo;Accademia indicated that they lived somewhere other than Florence.</p>"},{"id":"72c5f93b-76a0-46fe-9584-c478e1521fbc","content":"<p>Many surveyed visitors to the Galleria dell&rsquo;Accademia indicated that they would likely view the virtual tours in order to reminisce about their in-person visit.</p>"}]$SATQ$::jsonb, $SATQ$["A"]$SATQ$::jsonb, $SATQ$["2f741f4c-c41b-43c5-ad74-c659f55fa0ad"]$SATQ$::jsonb, $SATQ$<p>Choice A is the best answer because it presents a finding that, if true, would most directly support the museum administrators&rsquo; claim that concerns about virtual tours replacing in-person visits were unjustified. The text explains that after the Galleria dell&rsquo;Accademia began offering online tours, there were concerns that if people viewed these virtual tours, they would consider an in-person visit to be unnecessary. The finding that many visitors who were surveyed indicated that the virtual tours actually convinced them to plan an in-person visit directly contradicts these concerns. Rather than deterring in-person visits, virtual tours actively encouraged them, providing strong support for the administrators&rsquo; claim that the initial concerns were unfounded.</p><p>Choice B is incorrect. The finding that most surveyed visitors were unaware of the virtual tours before their first in-person visit wouldn&rsquo;t directly address whether virtual tours affect decisions about in-person visits. This finding would only indicate that these particular visitors didn&rsquo;t have the opportunity to be influenced by virtual tours when making their decision to visit. Choice C is incorrect because the geographic location of visitors wouldn&rsquo;t address the impact of virtual tours on people&rsquo;s decisions to visit the museum in person. Whether visitors live in Florence or elsewhere would suggest nothing about whether virtual tours influenced their choice. This information is irrelevant to the administrators&rsquo; claim about the relationship between virtual tours and in-person visits. Choice D is incorrect because visitors&rsquo; intentions to view virtual tours after their in-person visit wouldn&rsquo;t address the initial concerns that virtual tours might make in-person visits seem unnecessary. This finding indicates that some visitors plan to use virtual tours as a way to remember their visit, but it provides no information about whether virtual tours influenced their decision to visit in person in the first place, which is what the administrators&rsquo; claim addresses.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"98fd50f2","external_id":"4de54913-205f-481c-b12b-f64e8d8f81d7","vaultid":null,"uId":"d610f8d6-be44-4537-b08b-5c5548c9b286","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"INI","domain":"Information and Ideas","skill_cd":"COE","skill_desc":"Command of Evidence","difficulty":"M","score_band_range_cd":4,"type":"mcq","stimulus":"<p>Among the most visited art museums in the world, the Galleria dell&rsquo;Accademia in Florence had approximately 1.7 million visitors in 2019. The Galleria dell&rsquo;Accademia also offers virtual tours that art lovers can view online for free. Although there were initial concerns that people who viewed the virtual tours would then consider an in-person visit unnecessary, museum administrators claim that their surveys of in-person visitors show that those concerns were unjustified.</p>","stem":"<p>Which statement, if true, would most directly support the administrators&rsquo; claim?</p>","answerOptions":[{"id":"2f741f4c-c41b-43c5-ad74-c659f55fa0ad","content":"<p>Many surveyed visitors to the Galleria dell&rsquo;Accademia indicated that the virtual tours convinced them to plan an in-person visit.&nbsp;</p>"},{"id":"61a3f730-12d2-4a32-9d9b-d939e425d5fa","content":"<p>Most surveyed visitors to the Galleria dell&rsquo;Accademia indicated that they were unaware of the virtual tours before their first in-person visit.</p>"},{"id":"e133b8e7-98f4-42ab-9e74-4d2c5bddfeae","content":"<p>Most surveyed visitors to the Galleria dell&rsquo;Accademia indicated that they lived somewhere other than Florence.</p>"},{"id":"72c5f93b-76a0-46fe-9584-c478e1521fbc","content":"<p>Many surveyed visitors to the Galleria dell&rsquo;Accademia indicated that they would likely view the virtual tours in order to reminisce about their in-person visit.</p>"}],"keys":["2f741f4c-c41b-43c5-ad74-c659f55fa0ad"],"correct_answer":["A"],"rationale":"<p>Choice A is the best answer because it presents a finding that, if true, would most directly support the museum administrators&rsquo; claim that concerns about virtual tours replacing in-person visits were unjustified. The text explains that after the Galleria dell&rsquo;Accademia began offering online tours, there were concerns that if people viewed these virtual tours, they would consider an in-person visit to be unnecessary. The finding that many visitors who were surveyed indicated that the virtual tours actually convinced them to plan an in-person visit directly contradicts these concerns. Rather than deterring in-person visits, virtual tours actively encouraged them, providing strong support for the administrators&rsquo; claim that the initial concerns were unfounded.</p><p>Choice B is incorrect. The finding that most surveyed visitors were unaware of the virtual tours before their first in-person visit wouldn&rsquo;t directly address whether virtual tours affect decisions about in-person visits. This finding would only indicate that these particular visitors didn&rsquo;t have the opportunity to be influenced by virtual tours when making their decision to visit. Choice C is incorrect because the geographic location of visitors wouldn&rsquo;t address the impact of virtual tours on people&rsquo;s decisions to visit the museum in person. Whether visitors live in Florence or elsewhere would suggest nothing about whether virtual tours influenced their choice. This information is irrelevant to the administrators&rsquo; claim about the relationship between virtual tours and in-person visits. Choice D is incorrect because visitors&rsquo; intentions to view virtual tours after their in-person visit wouldn&rsquo;t address the initial concerns that virtual tours might make in-person visits seem unnecessary. This finding indicates that some visitors plan to use virtual tours as a way to remember their visit, but it provides no information about whether virtual tours influenced their decision to visit in person in the first place, which is what the administrators&rsquo; claim addresses.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1755117061177,"updateDate":1755117061177}$SATQ$::jsonb, 1755117061177, 1755117061177),
    ($SATQ$995d55fd$SATQ$, $SATQ$bf142dce-600d-4e0d-b6fc-80d7f0ae8ea8$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Information and Ideas$SATQ$, $SATQ$INI$SATQ$, $SATQ$CID$SATQ$, $SATQ$Central Ideas and Details$SATQ$, $SATQ$M$SATQ$, 4, $SATQ$mcq$SATQ$, $SATQ$<p>A subject of much speculation, distinctive sets of parallel ridges mark the icy crust of Europa, Jupiter&rsquo;s smallest moon. Researchers now claim that the ridges&rsquo; formation mechanism mirrors that of a strikingly similar pair on Greenland&rsquo;s ice sheet. There, surface water seeped through fissures in the sheet and formed a water pocket that subsequently disrupted the overlying ice, forcing fragments of it upward and outward into peaks, as the pocket froze and expanded. Although Europa lacks liquid surface water, the same process could be driven by the moon&rsquo;s subsurface ocean.</p>$SATQ$, $SATQ$<p>Which choice best states the main idea of the text?</p>$SATQ$, $SATQ$[{"id":"f8a542e4-fe68-47e1-ab20-53ece26a0df1","content":"<p>Researchers think that the ridges on Europa and the ridges in Greenland may have been formed by the same process even though Europa, unlike Greenland, doesn&rsquo;t have liquid water on its surface.</p>"},{"id":"8d61581d-1ad2-4918-bd81-2cae63dd066d","content":"<p>The primary difference between the ridges on Europa and the ridges in Greenland is that unlike the Europa ridges, the Greenland ridges are parallel.</p>"},{"id":"4cc83759-67c3-4822-890f-4d41c75d3e14","content":"<p>The pair of ridges found on Greenland&rsquo;s ice sheet appear to have formed long before the recently discovered sets of ridges on Europa formed.&nbsp;</p>"},{"id":"0d1bc1a6-047f-4c4e-8fb9-c6010f5403e6","content":"<p>Researchers don&rsquo;t understand why Europa is marked by so many sets of ridges when the moon doesn&rsquo;t have any liquid water on its surface that could have collected and expanded under the icy crust.</p>"}]$SATQ$::jsonb, $SATQ$["A"]$SATQ$::jsonb, $SATQ$["f8a542e4-fe68-47e1-ab20-53ece26a0df1"]$SATQ$::jsonb, $SATQ$<p>Choice A is the best answer because it accurately states the main idea of the text. The text focuses on formations of parallel ice ridges on Jupiter&rsquo;s moon Europa that are said to be formed by the same mechanism that formed a parallel set of ridges on Greenland&rsquo;s ice sheet. The text indicates that in Greenland, water on the surface seeps to the lower portion of the ice sheet, resulting in uplift that creates the ridges, and it states that although Europa lacks liquid water on its surface, the same process could be driven by an ocean below Europa&rsquo;s surface. In other words, the main idea of the text is that parallel ridges in the ice on Europa and Greenland are likely caused by similar processes even though in Greenland the process begins with liquid water on the surface while Europa lacks liquid water on the surface.</p><p>Choice B is incorrect because the text states outright that the ridges on Europa are parallel and furthermore refers to Greenland&rsquo;s ridges as "strikingly similar" to those on Europa. Choice C is incorrect because the text makes no mention of when any of the ice ridges formed, either separately or relative to one another. Choice D is incorrect because the text does not indicate any uncertainty about the reason for the ice ridges on Europa and, in fact, clearly states that researchers now claim to know the mechanism that created the ridges.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"995d55fd","external_id":"bf142dce-600d-4e0d-b6fc-80d7f0ae8ea8","vaultid":null,"uId":"7e7b2de7-8da0-4cc7-a518-461e7ce253c1","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"INI","domain":"Information and Ideas","skill_cd":"CID","skill_desc":"Central Ideas and Details","difficulty":"M","score_band_range_cd":4,"type":"mcq","stimulus":"<p>A subject of much speculation, distinctive sets of parallel ridges mark the icy crust of Europa, Jupiter&rsquo;s smallest moon. Researchers now claim that the ridges&rsquo; formation mechanism mirrors that of a strikingly similar pair on Greenland&rsquo;s ice sheet. There, surface water seeped through fissures in the sheet and formed a water pocket that subsequently disrupted the overlying ice, forcing fragments of it upward and outward into peaks, as the pocket froze and expanded. Although Europa lacks liquid surface water, the same process could be driven by the moon&rsquo;s subsurface ocean.</p>","stem":"<p>Which choice best states the main idea of the text?</p>","answerOptions":[{"id":"f8a542e4-fe68-47e1-ab20-53ece26a0df1","content":"<p>Researchers think that the ridges on Europa and the ridges in Greenland may have been formed by the same process even though Europa, unlike Greenland, doesn&rsquo;t have liquid water on its surface.</p>"},{"id":"8d61581d-1ad2-4918-bd81-2cae63dd066d","content":"<p>The primary difference between the ridges on Europa and the ridges in Greenland is that unlike the Europa ridges, the Greenland ridges are parallel.</p>"},{"id":"4cc83759-67c3-4822-890f-4d41c75d3e14","content":"<p>The pair of ridges found on Greenland&rsquo;s ice sheet appear to have formed long before the recently discovered sets of ridges on Europa formed.&nbsp;</p>"},{"id":"0d1bc1a6-047f-4c4e-8fb9-c6010f5403e6","content":"<p>Researchers don&rsquo;t understand why Europa is marked by so many sets of ridges when the moon doesn&rsquo;t have any liquid water on its surface that could have collected and expanded under the icy crust.</p>"}],"keys":["f8a542e4-fe68-47e1-ab20-53ece26a0df1"],"correct_answer":["A"],"rationale":"<p>Choice A is the best answer because it accurately states the main idea of the text. The text focuses on formations of parallel ice ridges on Jupiter&rsquo;s moon Europa that are said to be formed by the same mechanism that formed a parallel set of ridges on Greenland&rsquo;s ice sheet. The text indicates that in Greenland, water on the surface seeps to the lower portion of the ice sheet, resulting in uplift that creates the ridges, and it states that although Europa lacks liquid water on its surface, the same process could be driven by an ocean below Europa&rsquo;s surface. In other words, the main idea of the text is that parallel ridges in the ice on Europa and Greenland are likely caused by similar processes even though in Greenland the process begins with liquid water on the surface while Europa lacks liquid water on the surface.</p><p>Choice B is incorrect because the text states outright that the ridges on Europa are parallel and furthermore refers to Greenland&rsquo;s ridges as \"strikingly similar\" to those on Europa. Choice C is incorrect because the text makes no mention of when any of the ice ridges formed, either separately or relative to one another. Choice D is incorrect because the text does not indicate any uncertainty about the reason for the ice ridges on Europa and, in fact, clearly states that researchers now claim to know the mechanism that created the ridges.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1730147323034,"updateDate":1730147323034}$SATQ$::jsonb, 1730147323034, 1730147323034),
    ($SATQ$99fdf71c$SATQ$, $SATQ$32c4c072-059d-4cea-9e8c-d27888cc1845$SATQ$::uuid, $SATQ$9d2c8100-6391-44a6-98ba-5f6f0ba87978$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Information and Ideas$SATQ$, $SATQ$INI$SATQ$, $SATQ$COE$SATQ$, $SATQ$Command of Evidence$SATQ$, $SATQ$M$SATQ$, 5, $SATQ$mcq$SATQ$, $SATQ$<p>&ldquo;When Dawn Comes to the City&rdquo; is a 1922 poem by Claude McKay, who immigrated to the United States from the island nation of Jamaica as an adult. The poem conveys McKay&rsquo;s contrasting feelings about New York City&mdash;his adopted home in the US&mdash;and his home country: <span aria-hidden="true">______</span><span class="sr-only">blank</span></p>$SATQ$, $SATQ$<p>Which quotation from &ldquo;When Dawn Comes to the City&rdquo; most effectively illustrates the claim?</p>$SATQ$, $SATQ$[{"id":"e6586748-4981-4a79-b389-292530a40d5b","content":"<p>&ldquo;A lonely newsboy hurries by, / Humming a recent ditty; / Red streaks strike through the gray of the sky, / The dawn comes to the city [New York City].&rdquo;</p>"},{"id":"e9f6baae-077b-4767-b28c-d07bd4a8583a","content":"<p>&ldquo;Dark figures start for work; / I watch them sadly shuffle on, / &rsquo;Tis dawn, dawn in New York. / But I would be on the island of the sea, / In the heart of the island of the sea.&rdquo;</p>"},{"id":"68fa0768-2f61-4209-8411-8b29a4743d58","content":"<p>&ldquo;And the shaggy Nannie goat is calling, calling, calling / From her little trampled corner of the long wide lea / That stretches to the waters of the hill-stream falling / Sheer upon the flat rocks joyously!&rdquo;</p>"},{"id":"024ba1f7-dfe2-40f6-83f4-a729104b3eeb","content":"<p>&ldquo;The tired cars go grumbling by, / The moaning, groaning cars, / And the old milk carts go rumbling by / Under the same dull stars.&rdquo;</p>"}]$SATQ$::jsonb, $SATQ$["B"]$SATQ$::jsonb, $SATQ$["e9f6baae-077b-4767-b28c-d07bd4a8583a"]$SATQ$::jsonb, $SATQ$<p>Choice B is the best answer because it presents a quotation illustrating the claim that the poem conveys McKay&rsquo;s contrasting feelings about New York City and Jamaica. McKay first presents a somewhat negative view of New York City, describing watching &ldquo;dark figures&rdquo; who &ldquo;sadly shuffle&rdquo; to work at dawn, and then indicates that he would instead like to be &ldquo;in the heart of the island of the sea.&rdquo; </p><p>Choice A is incorrect because the quotation focuses on a description of only one place (New York City, with its &ldquo;lonely newsboy&rdquo; and &ldquo;red streaks&rdquo; in the sky at dawn) rather than on different feelings about two places. Choice C is incorrect because the quotation focuses on a description of only one place (which isn&rsquo;t named) rather than on McKay&rsquo;s different feelings about two places. Choice D is incorrect because though McKay presents a negative image of an unnamed place with &ldquo;tired cars&rdquo; that grumble, moan, and groan, and &ldquo;old milk carts&ldquo; that rumble by under &ldquo;dull stars,&rdquo; the quotation focuses on McKay&rsquo;s feelings about only one place rather than on different feelings about two places. </p>$SATQ$, false, 0, $SATQ$OSP-410-LIT$SATQ$, $SATQ$$SATQ$, $SATQ$8e44ebf7-1d9d-4e72-8c13-66fc1bce7275$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"99fdf71c","external_id":"32c4c072-059d-4cea-9e8c-d27888cc1845","vaultid":"9d2c8100-6391-44a6-98ba-5f6f0ba87978","uId":"805ff518-12f7-4261-a54d-eb49b80032c8","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"INI","domain":"Information and Ideas","skill_cd":"COE","skill_desc":"Command of Evidence","difficulty":"M","score_band_range_cd":5,"type":"mcq","stimulus":"<p>&ldquo;When Dawn Comes to the City&rdquo; is a 1922 poem by Claude McKay, who immigrated to the United States from the island nation of Jamaica as an adult. The poem conveys McKay&rsquo;s contrasting feelings about New York City&mdash;his adopted home in the US&mdash;and his home country: <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span></p>","stem":"<p>Which quotation from &ldquo;When Dawn Comes to the City&rdquo; most effectively illustrates the claim?</p>","answerOptions":[{"id":"e6586748-4981-4a79-b389-292530a40d5b","content":"<p>&ldquo;A lonely newsboy hurries by, / Humming a recent ditty; / Red streaks strike through the gray of the sky, / The dawn comes to the city [New York City].&rdquo;</p>"},{"id":"e9f6baae-077b-4767-b28c-d07bd4a8583a","content":"<p>&ldquo;Dark figures start for work; / I watch them sadly shuffle on, / &rsquo;Tis dawn, dawn in New York. / But I would be on the island of the sea, / In the heart of the island of the sea.&rdquo;</p>"},{"id":"68fa0768-2f61-4209-8411-8b29a4743d58","content":"<p>&ldquo;And the shaggy Nannie goat is calling, calling, calling / From her little trampled corner of the long wide lea / That stretches to the waters of the hill-stream falling / Sheer upon the flat rocks joyously!&rdquo;</p>"},{"id":"024ba1f7-dfe2-40f6-83f4-a729104b3eeb","content":"<p>&ldquo;The tired cars go grumbling by, / The moaning, groaning cars, / And the old milk carts go rumbling by / Under the same dull stars.&rdquo;</p>"}],"keys":["e9f6baae-077b-4767-b28c-d07bd4a8583a"],"correct_answer":["B"],"rationale":"<p>Choice B is the best answer because it presents a quotation illustrating the claim that the poem conveys McKay&rsquo;s contrasting feelings about New York City and Jamaica. McKay first presents a somewhat negative view of New York City, describing watching &ldquo;dark figures&rdquo; who &ldquo;sadly shuffle&rdquo; to work at dawn, and then indicates that he would instead like to be &ldquo;in the heart of the island of the sea.&rdquo; </p><p>Choice A is incorrect because the quotation focuses on a description of only one place (New York City, with its &ldquo;lonely newsboy&rdquo; and &ldquo;red streaks&rdquo; in the sky at dawn) rather than on different feelings about two places. Choice C is incorrect because the quotation focuses on a description of only one place (which isn&rsquo;t named) rather than on McKay&rsquo;s different feelings about two places. Choice D is incorrect because though McKay presents a negative image of an unnamed place with &ldquo;tired cars&rdquo; that grumble, moan, and groan, and &ldquo;old milk carts&ldquo; that rumble by under &ldquo;dull stars,&rdquo; the quotation focuses on McKay&rsquo;s feelings about only one place rather than on different feelings about two places. </p>","parenttemplatename":"OSP-410-LIT","parenttemplateid":"","templateclusterid":"8e44ebf7-1d9d-4e72-8c13-66fc1bce7275","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959336,"updateDate":1691007959336}$SATQ$::jsonb, 1691007959336, 1691007959336),
    ($SATQ$9aa5efc4$SATQ$, $SATQ$2986a17f-a6c9-4d76-9ddf-eedfb37e6eff$SATQ$::uuid, $SATQ$ddc5177d-f207-4a4d-8c40-421136fef60c$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Information and Ideas$SATQ$, $SATQ$INI$SATQ$, $SATQ$COE$SATQ$, $SATQ$Command of Evidence$SATQ$, $SATQ$M$SATQ$, 5, $SATQ$mcq$SATQ$, $SATQ$<p>Born in 1891 to a Quechua-speaking family in the Andes Mountains of Peru, Mart&iacute;n Chambi is today considered to be one of the most renowned figures of Latin American photography. In a paper for an art history class, a student claims that Chambi&rsquo;s photographs have considerable ethnographic value&mdash;in his work, Chambi was able to capture diverse elements of Peruvian society, representing his subjects with both dignity and authenticity.  </p>$SATQ$, $SATQ$<p>Which finding, if true, would most directly support the student&rsquo;s claim?</p>$SATQ$, $SATQ$[{"id":"848bb440-2d78-4dc4-a923-27f0c771ef0d","content":"<p>Chambi took many commissioned portraits of wealthy Peruvians, but he also produced hundreds of images carefully documenting the peoples, sites, and customs of Indigenous communities of the Andes.</p>"},{"id":"ca75a9b5-05c2-4ff3-89d1-1cdec985ad7a","content":"<p>Chambi&rsquo;s photographs demonstrate a high level of technical skill, as seen in his strategic use of illumination to create dramatic light and shadow contrasts. &nbsp;&nbsp;</p>"},{"id":"b699beda-9d3a-4b22-8ed1-9659dc0843ca","content":"<p>During his lifetime, Chambi was known and celebrated both within and outside his native Peru, as his work was published in places like Argentina, Spain, and Mexico.</p>"},{"id":"cfe639aa-ea57-42fd-b583-017a07a0f413","content":"<p>Some of the peoples and places Chambi photographed had long been popular subjects for Peruvian photographers.</p>"}]$SATQ$::jsonb, $SATQ$["A"]$SATQ$::jsonb, $SATQ$["848bb440-2d78-4dc4-a923-27f0c771ef0d"]$SATQ$::jsonb, $SATQ$<p>Choice A is the best answer because it presents a finding that, if true, would support the claim about Chambi&rsquo;s photographs. The text describes a student advancing the claim that Chambi&rsquo;s photographs &ldquo;have considerable ethnographic value&rdquo;&mdash;meaning that they are valuable as records of cultures&mdash;and that they &ldquo;capture diverse elements of Peruvian society&rdquo; in a respectful way. If it&rsquo;s true that Chambi carefully photographed people from a range of different communities in Peru as well as photographed the customs and sites of different communities, that would lend support to the claim that the photographs have ethnographic value as depictions of diverse elements of society in Peru.&nbsp;</p><p>Choice B is incorrect because the student&rsquo;s claim is that Chambi&rsquo;s photographs have considerable ethnographic value because they depict diverse elements of Peruvian society; the student doesn&rsquo;t claim anything about the technical skill demonstrated in the photographs.&nbsp;Choice C is incorrect because neither Chambi&rsquo;s reputation nor the locations where his photographs may have been published would be relevant to the student&rsquo;s claim that his photographs are valuable as an ethnographic record of Peru&rsquo;s diverse society.&nbsp;Choice D is incorrect because the popularity among other photographers of the people and places that Chambi photographed would be irrelevant to the student&rsquo;s claim that Chambi&rsquo;s photographs are valuable as an ethnographic record of Peru&rsquo;s diverse society.&nbsp;</p>$SATQ$, false, 0, $SATQ$OSP-306-TXT$SATQ$, $SATQ$$SATQ$, $SATQ$fe3a2443-b406-4101-aac2-a4aca571cdb1$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"9aa5efc4","external_id":"2986a17f-a6c9-4d76-9ddf-eedfb37e6eff","vaultid":"ddc5177d-f207-4a4d-8c40-421136fef60c","uId":"c010f8b5-b1f3-4d1f-848b-b4a251636482","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"INI","domain":"Information and Ideas","skill_cd":"COE","skill_desc":"Command of Evidence","difficulty":"M","score_band_range_cd":5,"type":"mcq","stimulus":"<p>Born in 1891 to a Quechua-speaking family in the Andes Mountains of Peru, Mart&iacute;n Chambi is today considered to be one of the most renowned figures of Latin American photography. In a paper for an art history class, a student claims that Chambi&rsquo;s photographs have considerable ethnographic value&mdash;in his work, Chambi was able to capture diverse elements of Peruvian society, representing his subjects with both dignity and authenticity.  </p>","stem":"<p>Which finding, if true, would most directly support the student&rsquo;s claim?</p>","answerOptions":[{"id":"848bb440-2d78-4dc4-a923-27f0c771ef0d","content":"<p>Chambi took many commissioned portraits of wealthy Peruvians, but he also produced hundreds of images carefully documenting the peoples, sites, and customs of Indigenous communities of the Andes.</p>"},{"id":"ca75a9b5-05c2-4ff3-89d1-1cdec985ad7a","content":"<p>Chambi&rsquo;s photographs demonstrate a high level of technical skill, as seen in his strategic use of illumination to create dramatic light and shadow contrasts. &nbsp;&nbsp;</p>"},{"id":"b699beda-9d3a-4b22-8ed1-9659dc0843ca","content":"<p>During his lifetime, Chambi was known and celebrated both within and outside his native Peru, as his work was published in places like Argentina, Spain, and Mexico.</p>"},{"id":"cfe639aa-ea57-42fd-b583-017a07a0f413","content":"<p>Some of the peoples and places Chambi photographed had long been popular subjects for Peruvian photographers.</p>"}],"keys":["848bb440-2d78-4dc4-a923-27f0c771ef0d"],"correct_answer":["A"],"rationale":"<p>Choice A is the best answer because it presents a finding that, if true, would support the claim about Chambi&rsquo;s photographs. The text describes a student advancing the claim that Chambi&rsquo;s photographs &ldquo;have considerable ethnographic value&rdquo;&mdash;meaning that they are valuable as records of cultures&mdash;and that they &ldquo;capture diverse elements of Peruvian society&rdquo; in a respectful way. If it&rsquo;s true that Chambi carefully photographed people from a range of different communities in Peru as well as photographed the customs and sites of different communities, that would lend support to the claim that the photographs have ethnographic value as depictions of diverse elements of society in Peru.&nbsp;</p><p>Choice B is incorrect because the student&rsquo;s claim is that Chambi&rsquo;s photographs have considerable ethnographic value because they depict diverse elements of Peruvian society; the student doesn&rsquo;t claim anything about the technical skill demonstrated in the photographs.&nbsp;Choice C is incorrect because neither Chambi&rsquo;s reputation nor the locations where his photographs may have been published would be relevant to the student&rsquo;s claim that his photographs are valuable as an ethnographic record of Peru&rsquo;s diverse society.&nbsp;Choice D is incorrect because the popularity among other photographers of the people and places that Chambi photographed would be irrelevant to the student&rsquo;s claim that Chambi&rsquo;s photographs are valuable as an ethnographic record of Peru&rsquo;s diverse society.&nbsp;</p>","parenttemplatename":"OSP-306-TXT","parenttemplateid":"","templateclusterid":"fe3a2443-b406-4101-aac2-a4aca571cdb1","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959335,"updateDate":1691007959335}$SATQ$::jsonb, 1691007959335, 1691007959335),
    ($SATQ$9abc3ba5$SATQ$, $SATQ$21326304-c438-42e3-b752-1c1d94c7369f$SATQ$::uuid, $SATQ$ef3f0896-e52e-4400-9389-d3864fff68cb$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Information and Ideas$SATQ$, $SATQ$INI$SATQ$, $SATQ$INF$SATQ$, $SATQ$Inferences$SATQ$, $SATQ$H$SATQ$, 6, $SATQ$mcq$SATQ$, $SATQ$<p>&ldquo;Gestures&rdquo; in painting are typically thought of as bold, expressive brushstrokes. In the 1970s, American painter Jack Whitten built a 12-foot (3.7-meter) tool he named the &ldquo;developer&rdquo; to apply paint to an entire canvas in one motion, resulting in his series of &ldquo;slab&rdquo; paintings from that decade. &nbsp;Whitten described this process as making an entire painting in &ldquo;one gesture,&rdquo; signaling a clear departure from the prevalence of gestures in his work from the 1960s. Some art historians claim this shift represents &ldquo;removing gesture&rdquo; from the process. Therefore, regardless of whether using the developer constitutes a gesture, both Whitten and these art historians likely agree that <span aria-hidden="true">______</span><span class="sr-only">blank</span></p>$SATQ$, $SATQ$<p>Which choice most logically completes the text?</p>$SATQ$, $SATQ$[{"id":"983ed87b-1155-4bc3-89ef-f74e053cd7f3","content":"<p>any tool that a painter uses to create an artwork is capable of creating gestures.</p>"},{"id":"b8c13007-52ab-417a-a2cb-c473b23160ab","content":"<p>Whitten&rsquo;s work from the 1960s exhibits many more gestures than his work from the 1970s does.</p>"},{"id":"73174fd7-7e20-4ab8-a5ba-faa36941714e","content":"<p>Whitten became less interested in exploring the role of gesture in his work as his career progressed.</p>"},{"id":"a175deea-b89e-4a81-a15b-d62d6a84e1f0","content":"<p>Whitten&rsquo;s work from the 1960s is much more realistic than his work from the 1970s is.</p>"}]$SATQ$::jsonb, $SATQ$["B"]$SATQ$::jsonb, $SATQ$["b8c13007-52ab-417a-a2cb-c473b23160ab"]$SATQ$::jsonb, $SATQ$<p>Choice B is the best answer. ​​Whitten thinks the tool made &ldquo;one gesture&rdquo; paintings, while historians think the tool &ldquo;removed gesture&rdquo; from the process completely. But putting that debate aside, both Whitten and the historians would agree that the paintings he made with the tool in the &rsquo;70s have way fewer gestures than his paintings from the &rsquo;60s, in which gestures are &ldquo;prevalent,&rdquo; meaning widely and extensively present. </p><p>Choice A is incorrect. This inference isn&rsquo;t supported. The text only discusses the &ldquo;developer&rdquo;&mdash;it never mentions other tools. Choice C is incorrect. This inference isn&rsquo;t supported. If anything, the text suggests the opposite: that Whitten became more interested in exploring the role of gesture in his work as his career progressed, as his earlier paintings had many gestures, and his &rsquo;70s paintings only had &ldquo;one gesture.&rdquo; Choice D is incorrect. This inference isn&rsquo;t supported. The text never discusses the &ldquo;realism&rdquo; of Whitten&rsquo;s art. </p>$SATQ$, false, 0, $SATQ$OSP-KA-INF-H002$SATQ$, $SATQ$$SATQ$, $SATQ$e72b23d0-0804-4207-8f7d-6934735996be$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"9abc3ba5","external_id":"21326304-c438-42e3-b752-1c1d94c7369f","vaultid":"ef3f0896-e52e-4400-9389-d3864fff68cb","uId":"d474ff43-2f17-4083-89be-88bd1146a88c","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"INI","domain":"Information and Ideas","skill_cd":"INF","skill_desc":"Inferences","difficulty":"H","score_band_range_cd":6,"type":"mcq","stimulus":"<p>&ldquo;Gestures&rdquo; in painting are typically thought of as bold, expressive brushstrokes. In the 1970s, American painter Jack Whitten built a 12-foot (3.7-meter) tool he named the &ldquo;developer&rdquo; to apply paint to an entire canvas in one motion, resulting in his series of &ldquo;slab&rdquo; paintings from that decade. &nbsp;Whitten described this process as making an entire painting in &ldquo;one gesture,&rdquo; signaling a clear departure from the prevalence of gestures in his work from the 1960s. Some art historians claim this shift represents &ldquo;removing gesture&rdquo; from the process. Therefore, regardless of whether using the developer constitutes a gesture, both Whitten and these art historians likely agree that <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span></p>","stem":"<p>Which choice most logically completes the text?</p>","answerOptions":[{"id":"983ed87b-1155-4bc3-89ef-f74e053cd7f3","content":"<p>any tool that a painter uses to create an artwork is capable of creating gestures.</p>"},{"id":"b8c13007-52ab-417a-a2cb-c473b23160ab","content":"<p>Whitten&rsquo;s work from the 1960s exhibits many more gestures than his work from the 1970s does.</p>"},{"id":"73174fd7-7e20-4ab8-a5ba-faa36941714e","content":"<p>Whitten became less interested in exploring the role of gesture in his work as his career progressed.</p>"},{"id":"a175deea-b89e-4a81-a15b-d62d6a84e1f0","content":"<p>Whitten&rsquo;s work from the 1960s is much more realistic than his work from the 1970s is.</p>"}],"keys":["b8c13007-52ab-417a-a2cb-c473b23160ab"],"correct_answer":["B"],"rationale":"<p>Choice B is the best answer. ​​Whitten thinks the tool made &ldquo;one gesture&rdquo; paintings, while historians think the tool &ldquo;removed gesture&rdquo; from the process completely. But putting that debate aside, both Whitten and the historians would agree that the paintings he made with the tool in the &rsquo;70s have way fewer gestures than his paintings from the &rsquo;60s, in which gestures are &ldquo;prevalent,&rdquo; meaning widely and extensively present. </p><p>Choice A is incorrect. This inference isn&rsquo;t supported. The text only discusses the &ldquo;developer&rdquo;&mdash;it never mentions other tools. Choice C is incorrect. This inference isn&rsquo;t supported. If anything, the text suggests the opposite: that Whitten became more interested in exploring the role of gesture in his work as his career progressed, as his earlier paintings had many gestures, and his &rsquo;70s paintings only had &ldquo;one gesture.&rdquo; Choice D is incorrect. This inference isn&rsquo;t supported. The text never discusses the &ldquo;realism&rdquo; of Whitten&rsquo;s art. </p>","parenttemplatename":"OSP-KA-INF-H002","parenttemplateid":"","templateclusterid":"e72b23d0-0804-4207-8f7d-6934735996be","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959368,"updateDate":1691007959368}$SATQ$::jsonb, 1691007959368, 1691007959368),
    ($SATQ$9c407117$SATQ$, $SATQ$9d63dd85-3fe2-4008-b144-de2a399f793e$SATQ$::uuid, $SATQ$e7560922-8484-4a2b-8626-91d0a5c9ca68$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Information and Ideas$SATQ$, $SATQ$INI$SATQ$, $SATQ$COE$SATQ$, $SATQ$Command of Evidence$SATQ$, $SATQ$H$SATQ$, 6, $SATQ$mcq$SATQ$, $SATQ$<p>A student performs an experiment testing her hypothesis that a slightly acidic soil environment is more beneficial for the growth of the plant <em>Brassica rapa parachinensis </em>(a vegetable commonly known as choy sum) than a neutral soil environment. She plants sixteen seeds of choy sum in a mixture of equal amounts of coffee grounds (which are highly acidic) and potting soil and another sixteen seeds in potting soil without coffee grounds as the control for the experiment. The two groups of seeds were exposed to the same growing conditions and monitored for three weeks.</p>$SATQ$, $SATQ$<p>Which finding, if true, would most directly weaken the student&rsquo;s hypothesis?</p>$SATQ$, $SATQ$[{"id":"257f489e-d504-4625-bead-95867e7eadc2","content":"<p>The choy sum planted in the soil without coffee grounds were significantly taller at the end of the experiment than the choy sum planted in the mixture of soil and coffee grounds.</p>"},{"id":"fa2e28df-1784-444d-95f3-8b0207b4c278","content":"<p>The choy sum grown in the soil without coffee grounds weighed significantly less at the end of the experiment than the choy sum grown in the mixture of soil and coffee grounds.</p>"},{"id":"0d3701e5-e063-48cb-a065-d3baca37807a","content":"<p>The choy sum seeds planted in the soil without coffee grounds sprouted significantly later in the experiment than did the seeds planted in the mixture of soil and coffee grounds.</p>"},{"id":"a05b1718-e0a2-4f03-ad87-0cc994ec8e3f","content":"<p>Significantly fewer of the choy sum seeds planted in the soil without coffee grounds sprouted plants than did the seeds planted in the mixture of soil and coffee grounds.</p>"}]$SATQ$::jsonb, $SATQ$["A"]$SATQ$::jsonb, $SATQ$["257f489e-d504-4625-bead-95867e7eadc2"]$SATQ$::jsonb, $SATQ$<p>Choice A is the best answer because it describes an experimental outcome that would most directly weaken the student&rsquo;s hypothesis. According to the text, the student hypothesizes that <em>Brassica rapa parachinensis </em>(choy sum) will benefit more from acidic soil than it will from neutral soil. The text then explains that the student planted 16 choy sum seeds in potting soil with coffee grounds added to increase acidity and another 16 seeds in soil without coffee grounds as a control (a group identical to the experimental group except for the experimental modification being tested). If the hypothesis were correct, the plants in the more acidic soil-and-coffee-grounds mixture would grow faster than those in the control group. However, choice A proposes a scenario in which the plants in soil without coffee grounds were &ldquo;significantly taller&rdquo; than those in the more acidic mixture&mdash;an outcome that weakens the hypothesis that higher acidity is beneficial to the plants&rsquo; growth. </p><p>Choice B is incorrect. If the choy sum planted in the neutral soil produced less plant matter and therefore weighed less than the choy sum planted in the acidic soil-and-coffee-grounds mixture, this finding would strengthen the student&rsquo;s hypothesis, not weaken it. Choice C is incorrect. If seeds planted in neutral soil (without coffee grounds) sprouted significantly later than seeds planted in the acidic soil-and-coffee-grounds mixture, this finding would strengthen, not weaken, the student&rsquo;s hypothesis that acidic soil benefits choy sum. Choice D is incorrect. If seeds planted in the neutral soil (without coffee grounds) sprouted significantly fewer plants than seeds planted in the acidic soil-and-coffee-grounds mixture did, this finding would strengthen, not weaken, the student&rsquo;s hypothesis that choy sum benefits from acidic soil. </p>$SATQ$, false, 0, $SATQ$OSP-313-TXT$SATQ$, $SATQ$$SATQ$, $SATQ$883d5a71-7116-4a4e-877a-baa8350a2fa2$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"9c407117","external_id":"9d63dd85-3fe2-4008-b144-de2a399f793e","vaultid":"e7560922-8484-4a2b-8626-91d0a5c9ca68","uId":"c86a2e5e-b694-4c3e-95dd-6942a13130c4","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"INI","domain":"Information and Ideas","skill_cd":"COE","skill_desc":"Command of Evidence","difficulty":"H","score_band_range_cd":6,"type":"mcq","stimulus":"<p>A student performs an experiment testing her hypothesis that a slightly acidic soil environment is more beneficial for the growth of the plant <em>Brassica rapa parachinensis </em>(a vegetable commonly known as choy sum) than a neutral soil environment. She plants sixteen seeds of choy sum in a mixture of equal amounts of coffee grounds (which are highly acidic) and potting soil and another sixteen seeds in potting soil without coffee grounds as the control for the experiment. The two groups of seeds were exposed to the same growing conditions and monitored for three weeks.</p>","stem":"<p>Which finding, if true, would most directly weaken the student&rsquo;s hypothesis?</p>","answerOptions":[{"id":"257f489e-d504-4625-bead-95867e7eadc2","content":"<p>The choy sum planted in the soil without coffee grounds were significantly taller at the end of the experiment than the choy sum planted in the mixture of soil and coffee grounds.</p>"},{"id":"fa2e28df-1784-444d-95f3-8b0207b4c278","content":"<p>The choy sum grown in the soil without coffee grounds weighed significantly less at the end of the experiment than the choy sum grown in the mixture of soil and coffee grounds.</p>"},{"id":"0d3701e5-e063-48cb-a065-d3baca37807a","content":"<p>The choy sum seeds planted in the soil without coffee grounds sprouted significantly later in the experiment than did the seeds planted in the mixture of soil and coffee grounds.</p>"},{"id":"a05b1718-e0a2-4f03-ad87-0cc994ec8e3f","content":"<p>Significantly fewer of the choy sum seeds planted in the soil without coffee grounds sprouted plants than did the seeds planted in the mixture of soil and coffee grounds.</p>"}],"keys":["257f489e-d504-4625-bead-95867e7eadc2"],"correct_answer":["A"],"rationale":"<p>Choice A is the best answer because it describes an experimental outcome that would most directly weaken the student&rsquo;s hypothesis. According to the text, the student hypothesizes that <em>Brassica rapa parachinensis </em>(choy sum) will benefit more from acidic soil than it will from neutral soil. The text then explains that the student planted 16 choy sum seeds in potting soil with coffee grounds added to increase acidity and another 16 seeds in soil without coffee grounds as a control (a group identical to the experimental group except for the experimental modification being tested). If the hypothesis were correct, the plants in the more acidic soil-and-coffee-grounds mixture would grow faster than those in the control group. However, choice A proposes a scenario in which the plants in soil without coffee grounds were &ldquo;significantly taller&rdquo; than those in the more acidic mixture&mdash;an outcome that weakens the hypothesis that higher acidity is beneficial to the plants&rsquo; growth. </p><p>Choice B is incorrect. If the choy sum planted in the neutral soil produced less plant matter and therefore weighed less than the choy sum planted in the acidic soil-and-coffee-grounds mixture, this finding would strengthen the student&rsquo;s hypothesis, not weaken it. Choice C is incorrect. If seeds planted in neutral soil (without coffee grounds) sprouted significantly later than seeds planted in the acidic soil-and-coffee-grounds mixture, this finding would strengthen, not weaken, the student&rsquo;s hypothesis that acidic soil benefits choy sum. Choice D is incorrect. If seeds planted in the neutral soil (without coffee grounds) sprouted significantly fewer plants than seeds planted in the acidic soil-and-coffee-grounds mixture did, this finding would strengthen, not weaken, the student&rsquo;s hypothesis that choy sum benefits from acidic soil. </p>","parenttemplatename":"OSP-313-TXT","parenttemplateid":"","templateclusterid":"883d5a71-7116-4a4e-877a-baa8350a2fa2","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959335,"updateDate":1691007959335}$SATQ$::jsonb, 1691007959335, 1691007959335),
    ($SATQ$9c591ff7$SATQ$, $SATQ$c53956b6-5cf4-4eb7-a7df-2139e74396c7$SATQ$::uuid, $SATQ$3ebcb0d3-b91f-4443-af39-8dbcc199b486$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Information and Ideas$SATQ$, $SATQ$INI$SATQ$, $SATQ$INF$SATQ$, $SATQ$Inferences$SATQ$, $SATQ$H$SATQ$, 6, $SATQ$mcq$SATQ$, $SATQ$<p>Some <em>Astyanax mexicanus</em>, a river-dwelling fish found in northeast Mexico, have colonized caves in the region. Although there is little genetic difference between river and cave&nbsp;<em>A. mexicanus</em> and all members of the species can emit the same sounds, biologist Carole Hyacinthe and colleagues found that the context and significance of those sounds vary by location&mdash;e.g., the click that river-dwelling <em>A. mexicanus</em> use to signal aggression is used by cave dwellers when foraging&mdash;and the acoustic properties of cave fish sounds show some cave-specific variations as well. Hyacinthe and colleagues note that differences in sonic communication could accumulate to the point of inhibiting interbreeding among fish from different locations, suggesting that&nbsp;<span aria-hidden="true">______</span><span class="sr-only">blank</span></p>$SATQ$, $SATQ$<p>Which choice most logically completes the text?</p>$SATQ$, $SATQ$[{"id":"a7880e4d-d708-4901-9c28-35f2eb26b88f","content":"<p>although <em>A. mexicanus</em> living in rivers are genetically similar to those living in caves, river fish rely on sonic communication less than cave fish do.</p>"},{"id":"325e26f1-0279-4ddb-b353-5bfde297b357","content":"<p>although <em>A. mexicanus</em> is a single species at present, it could be in the process of splitting into distinct populations with different characteristics.</p>"},{"id":"fc2c43fc-f628-4786-86fc-3f178bfe8c83","content":"<p>although all <em>A. mexicanus</em> emit sounds, the fish living in rivers produce some sounds that the fish living in caves do not, and vice versa.</p>"},{"id":"e1cb5ee1-b418-4bae-a968-8c3784289e99","content":"<p>although <em>A. mexicanus</em> from different locations can interbreed currently, river fish and cave fish are sufficiently genetically distinct that they can be considered separate species.</p>"}]$SATQ$::jsonb, $SATQ$["B"]$SATQ$::jsonb, $SATQ$["325e26f1-0279-4ddb-b353-5bfde297b357"]$SATQ$::jsonb, $SATQ$<p>Choice B is the best answer because it presents the conclusion that most logically follows from the text&rsquo;s discussion of <em>A. mexicanus</em>. According to the text, <em>A. mexicanus</em>, a river-dwelling fish species, has colonized caves. The fish that live in rivers and those that live in caves show no significant genetic differences and are all capable of making the same sounds. The text indicates, however, that Hyacinthe and colleagues found that sounds that the river fish use in a particular context and for a particular purpose are used in a different context and for a different purpose by the cave fish. Additionally, the sounds made by cave fish show some differences depending on the specific cave the fish inhabit. The text goes on to state that Hyacinthe and colleagues have noted that differences in how the fish use sound to communicate could eventually become so great that they prevent fish from different locations from interbreeding. In other words, the river fish might eventually only breed with other river fish (with whom they share characteristics regarding sonic communication that they do not share with cave fish), while the cave fish might only breed with other cave fish for a similar reason. In context, this observation suggests that even though the fish are a single species right now, they could be in the process of splitting into distinct populations with different characteristics.&nbsp;</p><p>Choice A is incorrect because there is no information in the text suggesting that the river fish are less reliant on sonic communication than the cave fish are. Although the text does indicate that the river fish and cave fish are genetically similar, the text describes both groups as using sonic communication and says nothing to indicate that one group depends on that communication more than the other group does. Choice C is incorrect. The text states that all members of the species can emit the same sounds but that the function and context of sounds differ depending on whether the fish live in rivers or caves, but it does not indicate that river fish produce sounds that cave fish do not or vice versa.&nbsp;Choice D is incorrect because it contradicts the text. The text says that there is little genetic difference between the river fish and the cave fish, not that the river fish and cave fish are so genetically distinct that they can be considered separate species. </p>$SATQ$, false, 0, $SATQ$OSP-063-INF$SATQ$, $SATQ$$SATQ$, $SATQ$6ea710a1-f500-4285-8d47-6ca582ed02da$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"9c591ff7","external_id":"c53956b6-5cf4-4eb7-a7df-2139e74396c7","vaultid":"3ebcb0d3-b91f-4443-af39-8dbcc199b486","uId":"503716c1-81db-4df2-9c5a-ac3ec15a14cc","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"INI","domain":"Information and Ideas","skill_cd":"INF","skill_desc":"Inferences","difficulty":"H","score_band_range_cd":6,"type":"mcq","stimulus":"<p>Some <em>Astyanax mexicanus</em>, a river-dwelling fish found in northeast Mexico, have colonized caves in the region. Although there is little genetic difference between river and cave&nbsp;<em>A. mexicanus</em> and all members of the species can emit the same sounds, biologist Carole Hyacinthe and colleagues found that the context and significance of those sounds vary by location&mdash;e.g., the click that river-dwelling <em>A. mexicanus</em> use to signal aggression is used by cave dwellers when foraging&mdash;and the acoustic properties of cave fish sounds show some cave-specific variations as well. Hyacinthe and colleagues note that differences in sonic communication could accumulate to the point of inhibiting interbreeding among fish from different locations, suggesting that&nbsp;<span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span></p>","stem":"<p>Which choice most logically completes the text?</p>","answerOptions":[{"id":"a7880e4d-d708-4901-9c28-35f2eb26b88f","content":"<p>although <em>A. mexicanus</em> living in rivers are genetically similar to those living in caves, river fish rely on sonic communication less than cave fish do.</p>"},{"id":"325e26f1-0279-4ddb-b353-5bfde297b357","content":"<p>although <em>A. mexicanus</em> is a single species at present, it could be in the process of splitting into distinct populations with different characteristics.</p>"},{"id":"fc2c43fc-f628-4786-86fc-3f178bfe8c83","content":"<p>although all <em>A. mexicanus</em> emit sounds, the fish living in rivers produce some sounds that the fish living in caves do not, and vice versa.</p>"},{"id":"e1cb5ee1-b418-4bae-a968-8c3784289e99","content":"<p>although <em>A. mexicanus</em> from different locations can interbreed currently, river fish and cave fish are sufficiently genetically distinct that they can be considered separate species.</p>"}],"keys":["325e26f1-0279-4ddb-b353-5bfde297b357"],"correct_answer":["B"],"rationale":"<p>Choice B is the best answer because it presents the conclusion that most logically follows from the text&rsquo;s discussion of <em>A. mexicanus</em>. According to the text, <em>A. mexicanus</em>, a river-dwelling fish species, has colonized caves. The fish that live in rivers and those that live in caves show no significant genetic differences and are all capable of making the same sounds. The text indicates, however, that Hyacinthe and colleagues found that sounds that the river fish use in a particular context and for a particular purpose are used in a different context and for a different purpose by the cave fish. Additionally, the sounds made by cave fish show some differences depending on the specific cave the fish inhabit. The text goes on to state that Hyacinthe and colleagues have noted that differences in how the fish use sound to communicate could eventually become so great that they prevent fish from different locations from interbreeding. In other words, the river fish might eventually only breed with other river fish (with whom they share characteristics regarding sonic communication that they do not share with cave fish), while the cave fish might only breed with other cave fish for a similar reason. In context, this observation suggests that even though the fish are a single species right now, they could be in the process of splitting into distinct populations with different characteristics.&nbsp;</p><p>Choice A is incorrect because there is no information in the text suggesting that the river fish are less reliant on sonic communication than the cave fish are. Although the text does indicate that the river fish and cave fish are genetically similar, the text describes both groups as using sonic communication and says nothing to indicate that one group depends on that communication more than the other group does. Choice C is incorrect. The text states that all members of the species can emit the same sounds but that the function and context of sounds differ depending on whether the fish live in rivers or caves, but it does not indicate that river fish produce sounds that cave fish do not or vice versa.&nbsp;Choice D is incorrect because it contradicts the text. The text says that there is little genetic difference between the river fish and the cave fish, not that the river fish and cave fish are so genetically distinct that they can be considered separate species. </p>","parenttemplatename":"OSP-063-INF","parenttemplateid":"","templateclusterid":"6ea710a1-f500-4285-8d47-6ca582ed02da","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959325,"updateDate":1691007959325}$SATQ$::json